// 自動生成: tools/build-why.mjs(375 問・1125 選択肢)。{ 問題id: { 不正解の選択肢の番号: [なぜ間違いか, [間違いに直結する部分...]] } }
export default {"AIB-C01-001":{"0":["正解ラベルを付ける作業は学習の前に行うデータ準備（アノテーション）です。完成したモデルを使って出力を得る推論とは別の工程です。",["正解のラベルを付ける"]],"1":["データを使ってモデルのパラメータを調整するのは学習（トレーニング）の説明です。推論は学習が終わったモデルを使う段階で、パラメータは変わりません。",["パラメータを調整する"]],"2":["評価用データで性能を測るのはモデルの評価の工程です。推論は新しい入力に対して予測や回答を得ることで、合否判定ではありません。",["性能を評価用データで測定し"]]},"AIB-C01-002":{"1":["項目名と値が決まった JSON は半構造化データで、表形式に変換しやすいデータです。音声や自由記述の文章のような非構造化データには当たりません。",["項目名と値が決まった形式"]],"2":["顧客マスタの CSV は行と列で項目が定義された表形式のデータで、構造化データです。非構造化データではありません。",["顧客マスタの CSV"]],"3":["会計システムの仕訳テーブルはデータベースの表に項目ごとに格納された構造化データです。音声や文章のような非構造化データではありません。",["仕訳テーブル"]]},"AIB-C01-003":{"0":["文書の長さに応じて自動的に上位モデルへ切り替わる仕組みはありません。利用するモデルは利用者が指定し、料金はそのモデルのトークン単価で決まります。",["自動的に上位のモデルに切り替わって"]],"1":["推論時にモデルが追加で学習することはありません。長い文書ほど高くなるのは、処理する入出力のトークン数が増えるためです。",["追加で学習を行う"]],"3":["オンデマンドの生成 AI の料金は利用者数ではなく入出力のトークン数で決まります。長い文書を利用者数として数える仕組みはありません。",["料金は利用者数で決まり"]]},"AIB-C01-004":{"0":["マネージドサービスでも、データのアクセス権の設定は利用企業の責任です。すべてを AWS が負うわけではなく、責任共有モデルに反します。",["すべて AWS が責任を負う"]],"1":["AWS が AI の出力内容の正確性を保証することはありません。出力をどう検証し業務に使うかは利用企業の責任です。",["正確性は AWS が保証し"]],"3":["マネージドサービスではソフトウェアの保守や運用も AWS が担います。物理的な安全だけを AWS が担うという分担は誤りです。",["ソフトウェアの保守は利用企業が行う"]]},"AIB-C01-005":{"0":["ルールベースは人があらかじめ条件を決めて判定する方式で、データから未知のグループを見つけることはできません。似た行動の顧客群の発見には向きません。",["ルールベースの判定"]],"2":["強化学習は行動に対する報酬をもとに最適な行動を学ぶ手法で、ロボット制御などに使われます。ラベルのない購買履歴からのグループ分けには使いません。",["強化学習"]],"3":["分類は正解ラベル付きのデータで学習する教師あり学習です。今回は正解ラベルがないため、分類モデルを学習できません。",["教師あり学習（分類）"]]},"AIB-C01-006":{"1":["人が条件分岐を書いたプログラムはルールベースのシステムで、データから学習したモデルではありません。多様なタスクに応用できる基盤モデルとは異なります。",["条件分岐として書いたプログラム"]],"2":["1 社の売上データだけで学習した予測モデルは特定用途向けの従来型 ML です。幅広いデータで事前学習し多様なタスクに使える基盤モデルとは異なります。",["1 社の売上データだけで学習した"]],"3":["データベースの設計図はスキーマや ER 図のことで、AI のモデルではありません。基盤モデルの説明とは無関係です。",["データベースの設計図"]]},"AIB-C01-007":{"1":["3 つは無関係ではなく包含関係にあります。ML は AI を実現する手法の一つで、ディープラーニングは ML の一分野です。",["互いに無関係な技術"]],"2":["包含関係が逆です。最も広い概念が AI で、その中に ML、さらにその中にディープラーニングがあります。",["ディープラーニングの中に ML があり"]],"3":["ML は AI の一部であって同じものではありません。またディープラーニングは ML の一分野なので AI に含まれます。",["同じもの","AI に含まれない"]]},"AIB-C01-008":{"0":["生成 AI は確率的に次の語を選ぶため、同じ質問でも表現が変わるのは通常の動作です。故障を示すものではありません。",["システムが故障している"]],"1":["生成 AI は入力が同じでも確率的なサンプリングで出力が変わることがあります。利用者の操作ミスではありません。",["出力は常に同じになるはず"]],"2":["出力のばらつきはキャッシュの削除とは関係なく、確率的な生成によるものです。表現が変わっても必ず誤りになるわけではありません。",["キャッシュから削除された","必ず誤った回答になる"]]},"AIB-C01-009":{"0":["同時利用者数はサービスの同時実行数やクォータの話で、コンテキストウィンドウとは無関係です。コンテキストウィンドウは 1 回に扱えるトークン数の上限です。",["同時に利用できる利用者の人数"]],"1":["学習に使ったデータの期間は知識のカットオフに関する話です。コンテキストウィンドウは 1 回の処理で扱える入出力の情報量の上限を指します。",["学習に使ったデータの期間"]],"2":["コンテキストウィンドウは画面表示の大きさではありません。モデルが 1 回の処理で入力と出力を合わせて扱えるトークン数の上限を指します。",["画面の大きさ"]]},"AIB-C01-010":{"0":["分類モデルは既存の選択肢から振り分けるだけで、新しい商品説明文を作れません。文章の作成は生成 AI が得意な領域です。",["過去の説明文を分類して流用する"]],"1":["生成 AI に売上表を渡して数値を生成させると、根拠や精度の検証が難しくなります。数値予測は過去データで学習する従来型 ML が適しています。",["売上予測も過去の売上表をプロンプトに入れて"]],"2":["組み合わせが逆です。数値の予測は従来型 ML、新しい文章の作成は生成 AI が適しており、分類モデルでは説明文を作れません。",["売上予測は生成 AI","従来型 ML の分類モデル"]]},"AIB-C01-011":{"0":["最新で高性能なモデルでもハルシネーションは起こりえます。モデル選定だけでは顧客に誤った回答が表示されるリスクを防げません。",["ハルシネーションは起きない"]],"2":["温度を 0 にすると出力のばらつきは減りますが、事実の誤りはなくなりません。設定変更だけでは顧客への誤回答を防げません。",["温度を 0 に設定すれば誤りはなくなる"]],"3":["注意書きを表示するだけでは誤った回答がそのまま顧客に届きます。出典の提示や人の確認など、影響を抑える仕組みが必要です。",["それ以外の対策は行わない"]]},"AIB-C01-012":{"2":["画像から不良品を見つけるには、見た目の多様なパターンを捉える必要があり、明確なルールで書き切れません。画像認識の AI が向く課題です。",["商品画像からの不良品検出"]],"3":["自由記述のメールは表現がさまざまで、キーワードのルールだけでは正確に分類しにくい課題です。自然言語処理の AI が向いています。",["内容に応じた自動分類"]],"4":["顧客ごとの購買傾向は複雑なパターンで、人がルールで書き切れません。データから学習する推薦の AI が向く課題です。",["購買傾向に基づく商品推薦"]]},"AIB-C01-013":{"0":["回帰モデルは査定額のような数値を予測するもので、写真と説明文を合わせて分析したり、査定の下書き文章を作ったりはできません。",["査定額を予測する回帰モデル"]],"2":["テキストのみを扱うモデルでは事故車の写真を入力できません。写真と説明文を合わせて分析する要件を満たせません。",["テキストのみを扱う"]],"3":["画像分類モデルは損傷の有無を判定するだけで、説明文を合わせた分析や査定の下書き文章の作成はできません。",["損傷の有無だけを判定する"]]},"AIB-C01-014":{"0":["画面のデザインは予測値そのものの精度に影響しません。検証では高精度なのに実データで外れるのは、モデルの汎化性能の問題です。",["画面のデザインが悪い"]],"1":["モデルの名前は予測の精度とは無関係です。検証で高精度、本番で外れるという現象は過学習の典型的な兆候です。",["モデルの名前"]],"3":["利用者が多いと応答の遅延などは起こりえますが、予測値が大きく外れる原因にはなりません。原因は新しいデータへの対応力の不足です。",["利用者が多すぎる"]]},"AIB-C01-015":{"0":["取引明細を要約しても、どの取引が不正かは判定できません。正常から外れた取引を検知するという目的に合いません。",["要約する生成 AI"]],"1":["時系列予測は件数の将来の推移を予測する手法で、個々の取引が不正かどうかは判定できません。",["取引件数を予測する時系列予測"]],"3":["顔写真の照合は本人確認の手段で、取引のパターンから不正利用を見つけるものではありません。新しい手口の検知にも対応できません。",["顔写真を照合する画像認識"]]},"AIB-C01-016":{"0":["他業界のデータで学習したモデルは、新規市場の状況を反映していません。根拠を検証せずにそのまま採用すると誤った経営判断につながります。",["他業界のデータで学習した","そのまま採用する"]],"2":["モデルのサイズを大きくしても、根拠となる過去データがなければ予測の精度は上がりません。データ不足という根本の問題は解決しません。",["モデルのサイズを大きくする"]],"3":["ML の予測は過去データのパターンに基づくため、データがない領域では信頼できません。どんなデータでも正確に予測できるという前提が誤りです。",["どのようなデータでも AI は正確に予測できる"]]},"AIB-C01-017":{"0":["生成 AI は確率的に出力するため、計算を誤ったり結果が毎回変わったりすることがあります。法令どおり常に同じ結果が必要な税額計算には向きません。",["生成 AI に毎回税額を計算させる"]],"1":["予測モデルは過去データから近似値を推定するもので、誤差が生じます。計算式で一意に決まる税額を正確に出す要件に合いません。",["過去の給与明細で学習した予測モデル"]],"3":["画像認識モデルは画像の内容を識別するもので、税額の計算はできません。業務の性質と無関係な技術です。",["画像認識モデル"]]},"AIB-C01-018":{"0":["音声認識は音声を文字に変換する技術で、契約条項どうしの意味の近さを比べることはできません。",["音声を文字に変換する音声認識"]],"1":["画像生成は文章から画像を作る技術で、意味の近い条項を探す検索には使えません。",["文章を画像に変換する画像生成"]],"2":["文字数を数えても文章の意味は比較できません。キーワードが一致しなくても内容の近い条項を探すには、意味をベクトルで表す必要があります。",["文字数を数える集計処理"]]},"AIB-C01-019":{"1":["温度を 0 にすると出力が安定する一方で多様性がなくなり、アイデア出しで幅広い案を得られません。用途に応じた使い分けが必要です。",["どちらも温度を 0 にする"]],"2":["温度を最大にすると出力のばらつきが大きくなり、社内規程に基づく定型回答の一貫性が損なわれます。",["どちらも温度を最大にする"]],"3":["温度は料金ではなく出力の多様性と安定性に影響するパラメータです。用途に応じて調整する必要があります。",["温度は料金だけに影響する"]]},"AIB-C01-020":{"0":["モデルが故意に古い情報を答えることはなく、学習データの時点（カットオフ）以降の知識を持たないのが原因です。言語を変えても解決しません。",["故意に古い情報を答えている"]],"1":["回答の文字数を増やしても、モデルが持たない最新の知識は得られません。最新の法令文書を外部から与える必要があります。",["回答の文字数を増やせば"]],"2":["生成 AI は学習した時点までの知識しか持たず、常に最新情報を知っているわけではありません。質問の仕方だけの問題ではありません。",["常に最新情報を知っている"]]},"AIB-C01-021":{"1":["生成 AI の評価だけを根拠にすると、偏りや誤りがそのまま採否に影響します。人の人生に関わる判断は人が責任を持って行う必要があります。",["唯一の根拠として採用する"]],"2":["本人の同意なく面接の録音を入力するのは、個人情報の適切な取り扱いに反します。プライバシーと法令遵守の面で問題があります。",["本人の同意なく"]],"3":["合否を生成 AI に決めさせてそのまま通知すると、人による確認や説明責任がなくなります。重要な判断を AI に丸投げすべきではありません。",["生成 AI に合否を決めさせ"]]},"AIB-C01-022":{"0":["学習にかかった時間は開発の効率の指標で、不良品の見逃しの多さは測れません。品質部門の要件と無関係です。",["学習にかかった時間"]],"2":["処理枚数は処理能力の指標で、不良品をどれだけ見逃したかは分かりません。見逃しを減らすには再現率を見る必要があります。",["処理できる画像の枚数"]],"3":["適合率は誤検知（良品を不良と判定）の少なさを測る指標です。今回は誤検知をある程度許容し見逃しを減らしたいので、重視すべきは再現率です。",["実際に不良だった割合（適合率）"]]},"AIB-C01-023":{"0":["画像生成モデルは画像を作るもので、検索窓の文字の候補を出す用途に合いません。応答速度やコストの要件以前に機能が異なります。",["画像生成モデル"]],"1":["モデルの規模は速度とコストに大きく影響します。大型のモデルほど応答が遅く、トークン単価も高くなる傾向があります。",["速度やコストに影響しない"]],"2":["最も大きいモデルは高品質でも応答が遅く高価で、大量アクセス時のコストが膨らみます。即時の候補表示という要件に合いません。",["常に最も大きく高性能なモデル"]]},"AIB-C01-024":{"0":["時系列モデルは出張件数の推移を予測するだけで、規程確認や登録、承認依頼といった手順を実行できません。",["出張件数を予測する時系列モデル"]],"1":["画像分類モデルは画像の内容を判定するだけで、複数システムにまたがる申請手続きを進めることはできません。",["画像を分類するモデル"]],"3":["1 回答えるだけのチャットボットは、計画を立ててツールや API を順に呼び出すことができません。複数ステップの業務を自動化できません。",["1 つの質問に 1 回答えるだけ"]]},"AIB-C01-025":{"0":["法定の計算式による集計は構造化データの決まった処理で、従来のプログラムで正確に行えます。非構造化データの活用でもありません。",["法定の計算式で集計する"]],"3":["社員番号の重複チェックは構造化データに対する単純な照合で、通常のプログラムで十分です。生成 AI を使う必要はありません。",["社員番号の重複をチェックする"]],"4":["決まった時刻の転記は定型のデータ連携で、ジョブのスケジュール実行などで自動化できます。生成 AI が得意な非構造化データの活用ではありません。",["決まった時刻に別システムへ転記する"]]},"AIB-C01-026":{"0":["他行のモデルは自行の顧客層や基準に合っているとは限りません。検証せずに使うと誤った否決が起き、当局への説明もできません。",["検証せずに使う"]],"1":["数百件のデータでは深層学習モデルは過学習しやすく、判断根拠の説明も困難です。説明責任が重い審査を全自動化するのは不適切です。",["数百件のデータで深層学習モデル"]],"3":["判断理由を記録しなければ、誤った否決について顧客や規制当局に説明できません。説明責任の要件に反します。",["判断理由を記録せずに"]]},"AIB-C01-027":{"0":["文章作成という生成 AI の利点まで捨てることになり、効率化の機会を失います。計算だけを確実な仕組みに切り分ければ両立できます。",["すべて手作業に戻す"]],"1":["計算に誤りがある資料を提出すると経営判断を誤らせます。文章が自然でも数値の正確さは保証されないため、検証と修正が必要です。",["そのまま経営会議に提出する"]],"2":["温度を最大にすると出力のばらつきが増え、計算の誤りはむしろ起きやすくなります。正確な計算の手段にはなりません。",["温度を最大にして"]]},"AIB-C01-028":{"0":["回答を長くしても誤りは減らず、むしろ誤った記述が増えるおそれがあります。誤りを目立たなくするのは苦情や法的リスクへの対策になりません。",["誤りが目立たないようにする"]],"1":["モデルの品質は継続的に評価しないと、誤回答の増加に気付けません。評価をやめるとハルシネーションの影響を把握できなくなります。",["評価を行わない"]],"2":["温度を高くすると出力のばらつきが増え、根拠のない内容が出やすくなります。正確さが重要な約款の回答には逆効果です。",["温度を高くして"]]},"AIB-C01-029":{"0":["生成 AI が出す数値は根拠や精度の検証が難しく、そのまま生産計画に使うと過剰生産や欠品につながります。数値予測には時系列予測モデルが適しています。",["出力された数値をそのまま生産計画に使う"]],"2":["技術の新しさは手法を選ぶ根拠になりません。生産計画に直接使う予測値を、精度の検証なしに採用するのは危険です。",["精度の検証なしに採用する"]],"3":["過去 5 年分の出荷実績と気象データが整っているのに使わないのは、精度の高い予測の機会を捨てることになります。",["データは使わない"]]},"AIB-C01-030":{"1":["正解率 85% のまま確認なしで自動入力すると、月 2 万件のうち多くの誤りが決算に混入します。99% 以上という要件を満たせません。",["確認なしで全件を自動入力する"]],"2":["算出方法を変えて数値をよく見せても、実際の誤りは減りません。決算への影響が残るうえ、不正確な報告は信頼を損ないます。",["算出方法を変えて 99% と報告する"]],"3":["AI 単体で要件に届かなくても、人の確認と組み合わせれば正確さを満たせる可能性があります。完全に断念すると人手不足を解消できません。",["完全に断念する"]]},"AIB-C01-031":{"0":["RPA は記録した固定手順を繰り返すだけで、目標に向けて自ら計画を立てたり判断したりはしません。AI エージェントとは異なります。",["画面操作の記録どおりに繰り返し実行する"]],"1":["登録済みの質問と回答に従うだけのチャットボットは、ツールを使って複数ステップの作業を自律的に進めることはできません。",["あらかじめ登録した質問と回答の組み合わせ"]],"3":["文書を検索して 1 回回答を生成するのは RAG の仕組みです。自ら計画を立てて複数ステップの作業を進めるエージェントとは異なります。",["根拠付きの回答文を 1 回生成する"]]},"AIB-C01-032":{"0":["Amazon Personalize は購買履歴などから推薦を行う特化型サービスです。複数の基盤モデルを比較してアプリに組み込む用途には使えません。",["Amazon Personalize"]],"2":["Amazon Polly はテキストを音声に変換する音声合成サービスです。複数の基盤モデルを選んで生成 AI を組み込む機能はありません。",["Amazon Polly"]],"3":["Amazon Comprehend は感情分析などのテキスト分析に特化したサービスです。複数社の基盤モデルを API で比較・利用する機能はありません。",["Amazon Comprehend"]]},"AIB-C01-033":{"0":["Amazon Personalize は推薦に特化したマネージドサービスで、任意の予測モデルを自由に開発・学習・デプロイする基盤ではありません。",["Amazon Personalize"]],"2":["Amazon Quick はビジネス向けの AI アシスタントや分析の機能で、データサイエンスチームが独自モデルを学習・デプロイする基盤ではありません。",["Amazon Quick"]],"3":["Bedrock Knowledge Bases は社内文書を検索して回答に使う RAG の仕組みです。独自の予測モデルを学習・デプロイする機能ではありません。",["Knowledge Bases"]]},"AIB-C01-034":{"0":["Amazon Polly はテキストを音声に変換するサービスで、音声を文字に起こす文字起こしとは処理が逆です。",["Amazon Polly"]],"1":["Amazon Rekognition は画像や動画を分析するサービスで、通話録音の音声を文字に起こす機能はありません。",["Amazon Rekognition"]],"2":["Amazon Translate はテキストを別の言語に翻訳するサービスで、音声を文字に起こすことはできません。",["Amazon Translate"]]},"AIB-C01-035":{"1":["Amazon Polly はテキストを音声に変換するサービスで、画像の内容を分析して不適切なものを検出することはできません。",["Amazon Polly"]],"2":["Amazon Comprehend はテキストの自然言語処理サービスで、画像に含まれる不適切な内容は検出できません。",["Amazon Comprehend"]],"3":["Amazon Transcribe は音声を文字に起こすサービスで、アップロードされた画像の内容をチェックする機能はありません。",["Amazon Transcribe"]]},"AIB-C01-036":{"1":["Amazon Rekognition は画像や動画を分析するサービスで、レビュー文章の感情分析やキーフレーズ抽出はできません。",["Amazon Rekognition"]],"2":["Amazon Textract は文書の画像や PDF から文字や表を抽出するサービスで、文章の感情やキーフレーズの分析は行いません。",["Amazon Textract"]],"3":["Amazon Polly はテキストを音声に変換するサービスで、レビューの感情分析やキーフレーズ抽出の機能はありません。",["Amazon Polly"]]},"AIB-C01-037":{"0":["音声合成サービスはテキストを音声にするもので、コードの生成や改善提案はできません。開発チームの生産性向上という目的に合いません。",["音声合成サービス"]],"2":["レコメンデーションサービスは購買履歴から商品を推薦するもので、コードの生成や説明を行う機能はありません。",["レコメンデーションサービス"]],"3":["画像分析サービスは画像や動画の内容を検出するもので、コードの生成や既存コードの改善提案には使えません。",["画像分析サービス"]]},"AIB-C01-038":{"0":["ゼロからの事前学習は大量のデータでモデル自体を作る工程で、プロンプトに例を示す手法ではありません。",["ゼロからの事前学習"]],"2":["ファインチューニングは追加データでモデルの重みを更新する手法です。プロンプトに例を含めるだけでモデルを変えない手法とは異なります。",["ファインチューニング"]],"3":["データの匿名化は個人情報を識別できないようにする処理で、例を示して出力の形を誘導するプロンプトの手法ではありません。",["データの匿名化"]]},"AIB-C01-039":{"0":["AWS Direct Connect はオンプレミスと AWS を専用線で接続するネットワークサービスで、生成 AI アプリの試作には使えません。",["AWS Direct Connect"]],"2":["AWS Snowball は大容量データを物理デバイスで AWS に移行するサービスで、ノーコードで生成 AI を試す環境ではありません。",["AWS Snowball"]],"3":["Amazon EBS は EC2 にアタッチするブロックストレージで、プログラミングなしで生成 AI アプリを試作する機能はありません。",["Amazon EBS"]]},"AIB-C01-040":{"0":["RAG は根拠となる文書を使うことで誤りを減らせますが、原理的になくなるわけではありません。人による確認の仕組みは引き続き必要です。",["誤りが原理的になくなり"]],"2":["知識をモデルの重みに組み込むのはファインチューニングの考え方です。RAG は回答時に文書を検索して使うため、文書がなければ回答できません。",["モデルの重みに組み込み"]],"3":["文体や口調を恒久的に合わせるのはファインチューニングの得意分野です。RAG の主な価値は最新の社内文書に基づいて回答できることです。",["文体や口調を自社のスタイルに恒久的に"]]},"AIB-C01-041":{"0":["RAG は事実情報の参照には向きますが、文体を安定して定着させる効果は限られます。プロンプトで安定しなかった文体の問題を解決しにくい方法です。",["RAG で検索させ"]],"1":["温度を上げると表現のばらつきが増え、ブランドの文体に一貫して合わせるという目的と逆の結果になります。",["温度を上げて"]],"3":["基盤モデルをゼロから事前学習するには膨大なデータとコスト、期間が必要です。文体を合わせるだけの目的には過剰です。",["ゼロから事前学習する"]]},"AIB-C01-042":{"1":["対象を短い提案書に限定すると業務の範囲が狭まるだけで、ばらつきの原因である曖昧な指示は改善されません。",["短い提案書に限定する"]],"2":["ファインチューニングはデータの準備や学習にコストと時間がかかります。プロンプトの改善で解決しない場合に検討する手段で、最初に試すものではありません。",["ファインチューニングを行う"]],"3":["高価なモデルへの切り替えはコストが増えるうえ、指示が曖昧なままではばらつきが残ります。まず低コストなプロンプトの改善を試すべきです。",["より高価で高性能なモデル"]]},"AIB-C01-043":{"0":["SageMaker AI での独自モデル開発はデータの準備や学習に時間がかかり、最も手早い導入という要件に合いません。",["独自の文書理解モデル"]],"1":["Amazon Rekognition は画像内の物体や顔の認識が主な用途で、請求書の金額や日付といった項目を構造的に抽出する用途には向きません。",["物体や顔を検出する Amazon Rekognition"]],"2":["Amazon Comprehend はテキストの感情やキーフレーズを分析するサービスで、PDF の請求書から金額や日付の項目を読み取る機能はありません。",["感情やキーフレーズを分析する"]]},"AIB-C01-044":{"1":["部署ごとに独自に工夫すると、良いプロンプトが共有されずばらつきが残ります。全社で品質をそろえるという目的に合いません。",["それぞれが独自にプロンプトを工夫する"]],"2":["1 つの汎用プロンプトに固定し変更を禁止すると、業務ごとの要件に対応できず、継続的な改善もできません。",["変更を禁止する"]],"3":["研修を一度行うだけでは、その後の品質は各自の力量に左右され、ばらつきが残ります。良いプロンプトの共有や改善の仕組みがありません。",["その後は各自に任せる"]]},"AIB-C01-045":{"0":["利用者に毎回書き添えてもらう方法では、書き忘れや書き方の違いで方針が守られません。利用者に依存せず一貫させる要件に合いません。",["利用者に毎回"]],"1":["後から手作業で削除するのは事後対応で、方針に反した回答が一度は利用者に届きます。運用の負荷も大きくなります。",["後から手作業で削除する"]],"2":["温度を最大にすると出力のばらつきが増え、丁寧語や回答範囲といった方針はむしろ守られにくくなります。",["温度を最大にする"]]},"AIB-C01-046":{"2":["短く答えるよう指示すると途中の検討が省かれ、複数の条件を見落として結論を誤りやすくなります。",["とにかく短く答えて"]],"3":["料金プランの情報を削除すると、モデルは根拠なく推測で比較することになり、誤りがかえって増えます。",["プロンプトから削除する"]],"4":["英語の大文字で書いても条件の整理や段階的な検討にはつながらず、比較の正確さは向上しません。",["英語の大文字で書く"]]},"AIB-C01-047":{"0":["担当者の記憶に頼ると、今回のように変更前の内容が分からず切り戻せません。担当者の異動などでも情報が失われます。",["担当者の記憶に任せる"]],"1":["原因がプロンプトの変更にあるのにモデルを切り替えても、問題の把握や再発防止にはなりません。変更履歴がない状態も変わりません。",["別のモデルに切り替える"]],"3":["プロンプトを一切変更しないと、品質の改善や業務の変化への対応ができなくなります。変更を管理して切り戻せるようにすべきです。",["今後一切変更しない"]]},"AIB-C01-048":{"0":["AWS Backup は AWS リソースのバックアップを一元管理するサービスで、プロンプトの作成やバージョン管理の機能はありません。",["AWS Backup"]],"1":["Amazon Route 53 は DNS サービスで、生成 AI アプリのプロンプトを作成・管理する機能はありません。",["Amazon Route 53"]],"2":["AWS Cost Explorer は利用料金の実績を分析するツールで、プロンプトを保存してバージョンを管理する機能はありません。",["AWS Cost Explorer"]]},"AIB-C01-049":{"0":["AWS Pricing Calculator は利用料金を見積もるツールで、社内文書を取り込んで検索し回答に使う仕組みは提供しません。",["AWS Pricing Calculator"]],"2":["Amazon Rekognition は画像や動画を分析するサービスで、マニュアルや FAQ を検索して回答する RAG の機能はありません。",["Amazon Rekognition"]],"3":["Amazon Polly はテキストを音声に変換するサービスで、社内文書の取り込みや検索の仕組みは提供しません。",["Amazon Polly"]]},"AIB-C01-050":{"1":["翻訳モデルをゼロから開発すると多大なデータとコスト、期間がかかります。標準的な翻訳を低コストで行う要件に合いません。",["ゼロから開発する"]],"2":["Amazon Transcribe は音声を文字に起こすサービスで、Web サイトの文章を他言語に翻訳する機能はありません。",["Amazon Transcribe"]],"3":["画像生成モデルは文章から画像を作るもので、案内文の機械翻訳には使えません。",["画像生成モデル"]]},"AIB-C01-051":{"1":["学習データの件数はプロンプトインジェクションへの耐性とは関係しません。指示の上書きを狙う入力を防ぐ対策にはなりません。",["学習データの件数を増やす"]],"2":["システムプロンプトでの禁止指示は、攻撃者の入力で上書きされるおそれがあります。機密情報を書き込むこと自体が漏えいの原因になります。",["システムプロンプトに機密情報を書き込み"]],"3":["温度は出力の多様性を調整するもので、攻撃への耐性とは無関係です。むしろ予期しない出力が増えるおそれがあります。",["温度を上げて"]]},"AIB-C01-052":{"1":["毎日ファインチューニングし直すと、学習のコストと手間が大きく、更新の反映にも時間差が出ます。頻繁に変わる情報には RAG が適しています。",["毎日モデルをファインチューニングし直す"]],"2":["物件データを与えなければ、モデルは最新の物件情報を知りません。言い回しを工夫しても正しい回答はできません。",["物件データをモデルに与えずに"]],"3":["基盤モデルをゼロから学習するのは膨大なコストと期間がかかり、毎日更新される情報にも追従できません。",["ゼロから学習させる"]]},"AIB-C01-053":{"0":["SageMaker AI での独自モデル開発には専門家が必要で、開発者に頼らず自然な言葉で分析するという条件に合いません。",["独自の予測モデルを開発する"]],"1":["Amazon Transcribe は音声を文字に起こすサービスで、売上データの分析やグラフの作成はできません。",["Amazon Transcribe"]],"2":["AWS Direct Connect はオンプレミスと AWS を専用線で結ぶネットワークサービスで、データ分析の機能はありません。",["AWS Direct Connect"]]},"AIB-C01-054":{"0":["Amazon Polly はテキストを音声に変換するサービスで、文書作成支援、生成 AI の組み込み、予測モデル開発のいずれにも対応できません。",["3 つとも Amazon Polly を使う"]],"1":["割り当てがずれています。SageMaker AI は ML 開発基盤で全社員の文書作成支援には向かず、独自の予測モデル開発には Bedrock ではなく SageMaker AI が適しています。",["①Amazon SageMaker AI","③Amazon Bedrock"]],"3":["すべてをゼロから開発すると時間とコストがかかり、すぐ使える文書作成支援や基盤モデルの組み込みで早く価値を出す機会を失います。",["ゼロから開発する"]]},"AIB-C01-055":{"0":["独自の基盤モデルをゼロから開発すると膨大なコストと期間がかかり、コストを抑えるという要件に反します。",["独自の基盤モデルをゼロから開発する"]],"1":["研究報告書を使わなければ、モデルは社内の研究内容を知らず、報告書に基づく質問応答ができません。",["研究報告書は使わず"]],"3":["毎週ファインチューニングし直すと学習コストがかさみ、追加される報告書の反映も遅れます。頻繁に変わる知識は RAG で参照する方が低コストです。",["毎週","ファインチューニングし直す"]]},"AIB-C01-056":{"1":["評価せずに本番へ反映すると、品質が下がっても苦情が出るまで気付けません。契約書チェックの誤りは業務に大きな影響を与えます。",["苦情が出たら考える"]],"2":["担当者 1 人の感想は主観的で、改善の根拠として不十分です。共通の評価データと基準で新旧を比較する必要があります。",["担当者の感想を根拠に"]],"3":["プロンプトは長いほど良いとは限らず、不要な指示が品質を下げることもあります。評価をせず長さで選ぶのは根拠がありません。",["長いプロンプトのほうが必ず良い"]]},"AIB-C01-057":{"1":["ルールで固定するとデータを使わないため、自社の閲覧・購買データに基づく推薦という要件を満たせません。",["データは使わない"]],"2":["SageMaker AI でゼロから推薦アルゴリズムを作るには ML の専門家が必要です。専門家不在で 3 か月以内に公開するという制約に合いません。",["推薦アルゴリズムをゼロから開発する"]],"3":["毎回すべての商品一覧を渡すとトークン数が膨らみコストが大きく、コンテキストウィンドウの上限も超えやすくなります。購買データに基づく推薦にもなりません。",["毎回すべての商品一覧を渡して"]]},"AIB-C01-058":{"1":["初日から全取引を完全自動化すると、誤りがあった場合に大量の誤った支払い登録が発生します。段階的な導入と人の確認が必要です。",["導入初日から全取引を完全に自動化する"]],"2":["管理者権限を与えると、誤動作や悪用の際に影響が全システムに及びます。最小権限の原則に反します。",["管理者権限をエージェントに与える"]],"3":["ログを無効にすると、エージェントが何をしたか追跡できず、誤りの原因究明や監査ができなくなります。",["ログを無効にする"]]},"AIB-C01-059":{"1":["音声認識と翻訳のモデルをゼロから開発するのは時間とコストがかかります。開発の手間を抑えるという要件に反します。",["SageMaker AI でゼロから開発する"]],"2":["Textract は文書の画像から文字を抽出するサービスで音声は扱えず、Comprehend はテキスト分析のサービスで翻訳はできません。",["音声を読み取り","Comprehend で翻訳する"]],"3":["Polly はテキストから音声を作るサービスで文字起こしの逆です。Rekognition は画像・動画の分析で、音声の翻訳はできません。",["Amazon Polly で音声を合成し"]]},"AIB-C01-060":{"0":["無料の一般向けサービスに社内文書を貼り付けると、情報漏えいのリスクがあり、社内のアクセス権限も反映されません。",["社内文書を自由に貼り付けて"]],"1":["アクセス権限の要件を外すと、閲覧権限のない社員が機密文書を見られてしまいます。セキュリティ要件に明確に反します。",["アクセス権限の要件を外して"]],"3":["IT 部門 3 名で機能ごとにゼロから開発すると、提供までに時間がかかり運用負荷も大きくなります。早く全社員に提供する要件に合いません。",["機能ごとにゼロから開発する"]]},"AIB-C01-061":{"0":["AWS Budgets は設定した予算に対する実績や予測を監視して通知するツールで、利用開始前の利用量から費用を見積もるものではありません。",["AWS Budgets"]],"2":["AWS Cost Explorer は過去の実績コストを分析するツールで、まだ運用していないアプリの月額を見積もるには向きません。",["AWS Cost Explorer"]],"3":["AWS Trusted Advisor は既存環境のコストやセキュリティの改善提案を行うツールで、想定利用量からの費用見積もりはできません。",["AWS Trusted Advisor"]]},"AIB-C01-062":{"0":["AWS Artifact は AWS のコンプライアンスレポートや契約を入手するサービスで、サードパーティーの AI ソリューションは購入できません。",["AWS Artifact"]],"1":["Generative AI Innovation Center は AWS の専門家による支援プログラムで、ソリューションを購入して AWS の請求にまとめる場ではありません。",["Innovation Center"]],"3":["AWS Skill Builder は AWS の学習コンテンツを提供するサービスで、業界向けの AI ソリューションを調達する仕組みはありません。",["AWS Skill Builder"]]},"AIB-C01-063":{"0":["他社事例は自社の経営目標や課題に合っているとは限りません。事例を起点にすると、技術ありきの施策になりやすくなります。",["同業他社が発表している AI 導入事例"]],"1":["部門の要望は参考になりますが、経営目標との整合を確認しないまま並べても優先順位を付けられません。戦略の出発点としては不十分です。",["AI で試したいことの要望一覧"]],"3":["利用可能な技術やツールから考えると、解くべき課題が後回しになり技術ありきの戦略になります。経営目標から逆算すべきです。",["AI 技術とツールの一覧"]]},"AIB-C01-064":{"1":["SWOT 分析は自社の強み・弱み・機会・脅威を整理する環境分析で、プレスリリースや FAQ を先に書いて顧客価値から逆算する手法ではありません。",["SWOT 分析"]],"2":["ウォーターフォール型の要件定義は開発工程を順に進める進め方で、完成後の顧客体験を文章化してから施策を固める手法ではありません。",["ウォーターフォール型の要件定義"]],"3":["ベンチマークテストはシステムやモデルの性能を測定する試験で、顧客にとっての価値から施策を逆算する企画手法ではありません。",["ベンチマークテスト"]]},"AIB-C01-065":{"0":["ライセンスの有効期間は契約上の期間で、投資額をいつ回収できるかとは関係ありません。",["ライセンスが有効な期間"]],"1":["学習の完了までの期間は開発の工程の話です。投資回収期間は累積の正味効果が初期投資額に達するまでの期間を指します。",["学習が完了するまでにかかる期間"]],"3":["パイロットの実施期間は検証の期間で、投資額を正味の効果で回収し終えるまでの期間とは異なります。",["パイロットの開始から終了までの期間"]]},"AIB-C01-066":{"0":["パラメータ数が最大のモデルが最適とは限らず、実現可能性の判断材料にもなりません。AI の成果はまず利用できるデータに左右されます。",["パラメータ数が最大かどうか"]],"1":["担当者の関心は推進力にはなりますが、ユースケースが技術的に実現できるかの判断材料にはなりません。データの有無を確認すべきです。",["担当者が AI に興味を持っているか"]],"3":["競合の動向は優先度の参考にはなっても、自社で実現できるかの判断材料にはなりません。必要なデータを利用できるかが中心です。",["競合他社がすでに同じ施策を発表しているか"]]},"AIB-C01-067":{"1":["撤退基準の目的は責任追及ではなく、客観的に継続・中止を判断して資源を適切に再配分することです。",["担当者の責任を問うため"]],"2":["撤退基準は成果が出ない施策を止めるためのもので、予算を自動的に増やす仕組みではありません。",["予算を毎年自動的に増額する"]],"3":["中止条件を決めても成功が保証されるわけではありません。成果が出ない場合に早く見切りを付けるための基準です。",["必ず成功させるため"]]},"AIB-C01-068":{"0":["AWS Artifact は AWS のコンプライアンス報告書を入手するサービスで、専門家と協力してユースケースの特定や概念実証を進めるプログラムではありません。",["AWS Artifact"]],"1":["AWS Health Dashboard は AWS サービスの障害やメンテナンスの情報を確認する仕組みで、生成 AI の活用を支援するプログラムではありません。",["AWS Health Dashboard"]],"2":["AWS Trusted Advisor はアカウントのコストやセキュリティなどのベストプラクティスを自動で確認するツールで、専門家による生成 AI の支援は行いません。",["AWS Trusted Advisor"]]},"AIB-C01-069":{"0":["価値だけで選ぶと、データ不足やリスクの高さで頓挫しやすくなります。実現可能性もあわせて評価する必要があります。",["実現の難しさに関係なく選ぶ"]],"1":["各部門から同時に着手すると資源が分散し、どの案件も成果が出にくくなります。価値と実現性で絞り込むべきです。",["公平に同時に着手する"]],"2":["最新技術を試せるかは技術者側の動機で、ビジネス価値や実現可能性を基準にしていません。成果が出にくい案件を選ぶおそれがあります。",["最新の生成 AI 技術を試せる案件"]]},"AIB-C01-070":{"1":["利用回数の伸びは関心の高さを示すだけで、業務成果や本番運用のコストを示しません。展開判断の主な根拠にはなりません。",["利用回数の伸び"]],"2":["モデルが最新かどうかは業務成果と直接関係しません。事前に合意した KPI の達成状況とコスト・リスクで判断すべきです。",["現在も最新のモデルであるかどうか"]],"3":["使いやすさの評価は参考になりますが、業務成果やスケール時のコストを示すものではありません。",["「使いやすい」と答えた割合"]]},"AIB-C01-071":{"1":["初期費用だけで選ぶと、施策から得られる便益の大きさを比較できません。期待価値と機会費用を含めて判断すべきです。",["初期費用が少ないほうを選び"]],"2":["予算を半分ずつに分けると、どちらの施策も資源不足で中途半端になりやすく、成果が出にくくなります。",["半分ずつ配分し"]],"3":["すでにかけた時間は埋没費用で、今後の価値とは関係ありません。これを理由に選ぶと判断を誤ります。",["これまでの投資を無駄にしない"]]},"AIB-C01-072":{"0":["データが整っていない案件は準備に時間がかかり、早期に成果を示すことができません。",["データが整っていない"]],"1":["3 年かかる全社の刷新は成果が出るまでに長い期間が必要で、早く成果を示して支持を得るという目的に合いません。",["3 年かかる全社基幹システムの AI 刷新"]],"3":["規制上のリスクが大きい自動与信判断は、検証や説明責任への対応に時間がかかり、最初の施策としては失敗の影響も大きくなります。",["規制上のリスクが大きい"]]},"AIB-C01-073":{"0":["データサイエンティストの採用から始めると時間とコストがかかり、初期投資を抑えて数週間で試すという要件に合いません。",["データサイエンティストを 10 名採用してから"]],"1":["GPU サーバーの購入と独自モデルの事前学習は多額の投資と長い期間が必要で、専門チームのない 200 名規模の企業には過剰です。",["独自の大規模言語モデルを事前学習する"]],"3":["生成 AI の要約が 100% 正確になることはありません。この基準では導入できず、数週間で試すという要件も満たせません。",["確実に 100% になるまで"]]},"AIB-C01-074":{"0":["サーバーを常時稼働させると、処理していない時間も費用がかかります。翌朝までにまとめて処理すればよい要件に対して割高です。",["サーバーを常時稼働させる"]],"1":["即時性が不要なのに 1 件ずつリアルタイムで高性能モデルを使うと、単価が高くなりコストを抑える要件に反します。",["1 件ずつリアルタイムで処理し"]],"3":["毎月 50 万件を人手で分類すると人件費が膨大になり、かえってコストが増えます。生成 AI のバッチ処理で十分対応できます。",["分類は人手で行う"]]},"AIB-C01-075":{"1":["成功時の効果だけで比べると不確実性を見落とします。期待価値は施策 X が 3,000 万円で、施策 Y の 4,000 万円より小さくなります。",["施策 X を必ず優先する"]],"2":["成功確率が 100% の施策はほとんどありません。期待価値で比較すれば、施策 Y は投資する価値があると判断できます。",["どちらも実施しない"]],"3":["予算は 1 件分のみで、半分ずつに分けるとどちらも中途半端になりやすくなります。期待価値の高い施策 Y に集中すべきです。",["半分ずつに分けて同時に進める"]]},"AIB-C01-076":{"0":["1,800 万円を毎月の正味効果 150 万円で割ると 12 か月です。18 か月は計算が誤っています。",["18 か月"]],"1":["1,800 万円 ÷ 150 万円 = 12 か月で、6 か月では累積の正味効果は 900 万円にしかならず、初期投資を回収できていません。",["6 か月"]],"2":["1,800 万円 ÷ 150 万円 = 12 か月です。24 か月では累積効果が 3,600 万円となり、回収期間を過大に見積もっています。",["24 か月"]]},"AIB-C01-077":{"0":["汎用の既製品は自社データに合わせた調整ができないと問題文で示されています。自社の配送データに基づく予測という要件を満たせません。",["調整のできない汎用の既製品"]],"2":["施策を凍結すると、半年以内に導入するという期限を守れません。不足する専門性はパートナーで補えます。",["施策を凍結する"]],"3":["専門チームを一から採用・育成するには長い時間がかかり、半年以内の導入に間に合いません。",["一から採用・育成してから"]]},"AIB-C01-078":{"0":["楽観的な利用量だけの試算では、利用が想定を上回った場合の予算超過のリスクを見落とします。",["最も楽観的な利用量だけで試算し"]],"2":["見通しを出さないと財務部門は予算を組めません。不確実でも前提を示した試算を出すべきです。",["費用の見通しは出さない"]],"3":["前年の IT 予算は新しい生成 AI サービスの利用量や料金とは無関係で、根拠のある見通しになりません。",["前年の IT 予算と同額になる"]]},"AIB-C01-079":{"0":["施策に関係しない部門の新入社員は、業務課題や法的なリスクを判断する立場にありません。",["施策に関係しない部門の新入社員"]],"1":["競合企業の担当者を巻き込むと、自社の戦略や顧客データに関する情報が漏れるおそれがあります。",["競合企業の担当者"]],"2":["個別の施策の初期検討に社外の株主全員を巻き込むのは現実的ではなく、業務や法務の判断にも役立ちません。",["社外の株主全員"]]},"AIB-C01-080":{"0":["業務データがまったくないと、AI の精度も導入前後の効果も測れません。最初のパイロットには不向きです。",["業務データがまったく存在しない"]],"1":["最も大規模で複雑な基幹業務は失敗時の影響が大きく、成果が出るまでにも時間がかかります。最初の対象には不向きです。",["最も規模が大きく複雑な基幹業務"]],"3":["関係者が多く合意形成に時間がかかる業務は、パイロットの開始や判断が遅れ、短期間で学びを得にくくなります。",["合意形成に時間がかかる"]]},"AIB-C01-081":{"1":["利用量が少なく変動する段階で最大利用量の容量を確保すると、使わない分の費用が無駄になります。",["最初から長期間の容量を確保する"]],"2":["Amazon Bedrock のオンデマンド料金はトークン数などの利用量に応じて変わります。料金が一定という前提が誤りです。",["利用量に関係なく一定"]],"3":["利用量の変動を理由にサービスを停止する必要はありません。従量課金なら使った分だけの支払いで済みます。",["サービスを停止する"]]},"AIB-C01-082":{"0":["個人の無料チャットでは、データの保管場所や学習への不使用を契約で確認できず、未公開の経営情報を管理できません。",["個人で無料の生成 AI チャット"]],"2":["開発者の採用と体制づくりを待つと、3 か月以内に全社で使えるようにする期限に間に合いません。",["体制が整ってから自社で要約機能を開発する"]],"3":["差別化につながらない機能を開発者がほとんどいない状態でゼロから作ると、期限に間に合わずコストも高くなります。",["自社でゼロから開発する"]]},"AIB-C01-083":{"0":["効果が不確実なまま全社展開の予算を一括で確保すると、効果がなかった場合の損失が大きく、財務部門の懸念に反します。",["予算を一括で確保して導入し"]],"1":["効果が未確認のまま 3 年契約で一斉展開すると、効果がなかった場合に解約できず損失が大きくなります。",["3 年契約を結んで全営業部門に一斉展開する"]],"3":["競合の結果を待つと導入が遅れ、競合に後れを取るという経営陣の懸念に応えられません。",["競合の導入結果が公表されるまで待ち"]]},"AIB-C01-084":{"0":["最も安いモデルで一律に処理すると、高い正確性が必要な契約・料金の回答で誤りが増えます。注意書きだけでは苦情や返金を防げません。",["最も安いモデルで処理し"]],"2":["中位モデルの一律適用では契約・料金の回答の正確性が不十分なおそれがあり、苦情が来てからの対応では返金などの損失を防げません。",["苦情が来た時点で個別に対応する"]],"3":["9 割の一般的な質問まで最高性能のモデルで処理すると、件数の倍増で予算を超えます。件数の上限は顧客対応の低下につながります。",["すべての問い合わせを最も高性能なモデルで処理する"]]},"AIB-C01-085":{"0":["すべてを 1 年間の ROI で評価すると、3 年後の顧客満足度を高める戦略的な施策が一律に却下され、顧客体験の責任者の支持を失います。",["同じ 1 年間の ROI 基準で評価し"]],"1":["短期の施策だけに集中すると中長期の戦略的施策が排除され、顧客体験の責任者の支持を失います。",["中長期の施策は検討しない"]],"2":["同額を配分して評価を任せると、全社としての優先順位や評価基準がなくなり、経営層として施策を管理できません。",["評価はそれぞれに任せる"]]},"AIB-C01-086":{"0":["パイロットで作業時間 20% 削減と高い評価という成果が出ています。モデルやプロンプトの見直しで採算が合う可能性があり、即時の中止は情報を活かしていません。",["直ちに完全に中止する"]],"1":["コスト試算を隠して展開後に予算を追加申請するのは、経営層の適切な判断を妨げ、組織の信頼を損ないます。",["コストの試算を公表せず"]],"3":["試算では利用料が人件費削減額を上回るため、そのまま全社展開すると赤字が続きます。利用者の評価だけでは採算の問題は解決しません。",["試算のとおり全社展開する"]]},"AIB-C01-087":{"0":["審査の仕組みが見えない汎用 SaaS では、判断根拠の説明やデータを自社管理下に置く規制要件を満たしにくく、独自ノウハウも生かせません。",["審査の仕組みが外部から見えない汎用の SaaS"]],"1":["大規模言語モデルを一から事前学習するのは膨大なコストと期間がかかり過剰です。マネージドな基盤モデルと自社データの組み合わせで十分です。",["一から事前学習する"]],"2":["差別化領域だからこそ、自社ノウハウを組み込んだ AI で競争力を高められます。AI を使わないと効率化や品質向上の機会を逃します。",["AI は使わず従来どおり人手で審査を続ける"]]},"AIB-C01-088":{"0":["AWS Pricing Calculator は利用開始前の見積もり用のツールで、実際の利用料金の推移を分析することはできません。",["AWS Pricing Calculator"]],"1":["AWS CloudTrail は API 操作の記録を残すサービスで、利用料金の推移を部門別に分析する機能はありません。",["AWS CloudTrail"]],"2":["AWS Budgets は予算のしきい値を超えたときに通知するツールで、それだけでは料金の推移を部門別に詳しく分析できません。",["AWS Budgets のみ"]]},"AIB-C01-089":{"0":["記憶に基づく回答は不正確で、導入前の実態を反映しません。導入前に実測したベースラインが必要です。",["導入前の処理時間を思い出して"]],"2":["導入後の値を基準にすると、導入による効果が基準値に含まれてしまい、導入前後の比較ができません。",["導入後 1 か月の指標を基準値とし"]],"3":["業界平均の改善率は自社の業務の実態を反映せず、自社での導入前後の効果を測る基準になりません。",["業界平均の改善率"]]},"AIB-C01-090":{"0":["利用者数は利用状況の指標で、業務成果が維持されているかは分かりません。成果の低下を見落とすおそれがあります。",["利用者数が増え続けている限り"]],"1":["データや業務の変化で効果は変わるため、年 1 回の確認では悪化に気付くのが遅れます。継続的なモニタリングが必要です。",["年 1 回の決算時にのみ確認する"]],"3":["稼働率や応答時間は技術的な指標で、業務成果の低下は分かりません。KPI を継続的に追跡する必要があります。",["稼働率と応答時間だけを監視し"]]},"AIB-C01-091":{"1":["年間の顧客離反率は結果として後から表れる遅行指標で、早い段階で変化が見える先行指標ではありません。",["年間の顧客離反率"]],"2":["年度末の売上高は施策の結果として後から確定する遅行指標です。",["年度末の売上高"]],"3":["前年度の営業利益は過去の結果で、AI 導入の効果を早期に示す先行指標にはなりません。",["前年度の営業利益"]]},"AIB-C01-092":{"0":["対照群は比較のために設けるもので、そのグループの業務を減らすことが目的ではありません。",["業務を減らすため"]],"2":["対照群を設けても AI の利用料が半分になるわけではありません。目的は外部要因を除いて AI の効果を切り分けることです。",["AI の利用料を半分にする"]],"3":["対照群を設けると比較のためのデータはむしろ必要になります。データ量を減らすことが目的ではありません。",["データ量を減らすため"]]},"AIB-C01-093":{"0":["AWS Marketplace はサードパーティーのソフトウェアを購入する場で、予算の上限に近づいたときに通知する機能はありません。",["AWS Marketplace"]],"1":["AWS Artifact はコンプライアンス報告書を入手するサービスで、費用を監視して通知する機能はありません。",["AWS Artifact"]],"2":["AWS Pricing Calculator は導入前に費用を見積もるツールで、実際の費用を監視して通知することはできません。",["AWS Pricing Calculator"]]},"AIB-C01-094":{"0":["サーバーの台数はインフラの規模を示すだけで、問い合わせ対応の費用対効果を表しません。マネージドサービスでは台数自体を意識しないこともあります。",["導入したサーバーの台数"]],"1":["モデルの名前は費用対効果を示す指標になりません。",["モデルの名前"]],"2":["総額だけでは、利用量が増えたのか効率が悪化したのかを区別できず、利用量が変わる中での比較に向きません。",["総額のみ"]]},"AIB-C01-095":{"0":["GPU の数は計算資源の量で、下書きが業務で実際に使える品質かどうかは分かりません。",["GPU の数"]],"1":["画面のデザインの評価は使い勝手の話で、生成された下書きの内容が実務で役立っているかを示しません。",["画面のデザインの評価"]],"3":["総文字数は生成量を示すだけで、下書きがそのまま使える品質かどうかは分かりません。",["総文字数"]]},"AIB-C01-096":{"0":["リクエスト数は利用量の指標で、サポート業務の成果が上がったかは分かりません。補助的な指標にとどまります。",["1 日あたりのリクエスト数"]],"1":["平均トークン数は応答の長さを示すだけで、問い合わせの解決や効率化といった業務成果を表しません。",["平均トークン数"]],"2":["アカウントの付与人数は導入範囲を示すだけで、ビジネス価値を示す KPI にはなりません。",["アカウントを付与された人数"]]},"AIB-C01-097":{"0":["平均応答時間は測定できる性能の指標で、数値化しにくい便益ではありません。それ自体は業務上の便益も示しません。",["平均応答時間"]],"1":["質問件数は測定できる利用の指標で、数値化しにくい定性的な便益には当たりません。",["1 日あたりの質問件数"]],"2":["月間アクティブ利用者数は定量的な利用指標で、従業員体験の向上のような定性的な便益を示すものではありません。",["月間アクティブ利用者数"]]},"AIB-C01-098":{"1":["会議の回数は社内の活動量を示すだけで、広告やキャンペーンの成果を表しません。",["AI に関する会議を開いた回数"]],"3":["トークンの合計数は利用量やコストの目安にすぎず、顧客の行動や制作効率といったビジネス成果を示しません。",["トークンの合計数"]],"4":["利用したモデルの数は技術的な構成の話で、施策のビジネス成果とは関係ありません。",["利用した基盤モデルの数"]]},"AIB-C01-099":{"0":["12 月は全店で売上が増える時期のため、前月比 15% には季節要因が含まれます。そのまま AI の効果とすると過大評価になります。",["そのまま AI の効果として報告する"]],"1":["予測精度だけでは売上などのビジネス成果への寄与が分かりません。季節要因を除いた効果を示す必要があります。",["予測精度だけを報告する"]],"2":["店長の印象は主観的で、季節要因と AI の効果を切り分けられません。",["店長の印象を集めて"]]},"AIB-C01-100":{"0":["アカウントの総数もログイン数と同じく活動の量を示すだけで、業務成果や投資効果は分かりません。",["利用者アカウントの総数"]],"1":["紹介ページへのアクセス数は関心の高さを示すにすぎず、業務成果に結び付く指標ではありません。",["紹介ページへのアクセス数"]],"3":["ログイン画面の表示回数はログイン数と同様の見栄えだけの指標で、投資効果の判断に使えません。",["ログイン画面の表示回数"]]},"AIB-C01-101":{"0":["生成コードの行数は量を示すだけで、品質や開発の速さが向上したかは分かりません。行数が多いほど良いわけでもありません。",["AI が生成したコードの行数"]],"1":["ツールの起動回数は利用量の指標で、事業への効果を示すものではありません。",["AI ツールを起動した回数"]],"3":["座席数はチームの規模を示すだけで、AI コーディングアシスタントの効果とは無関係です。",["開発チームの座席数"]]},"AIB-C01-102":{"0":["月額利用料はコストの指標で、通話時間の短縮によって応対品質が下がっていないかは確認できません。",["AI の利用料の月額"]],"2":["電話機の台数は設備の規模を示すだけで、応対品質を表す指標ではありません。",["使用している電話機の台数"]],"3":["出勤時刻は勤怠の情報で、顧客への応対品質とは関係ありません。",["オペレーターの出勤時刻"]]},"AIB-C01-103":{"1":["料金が高いモデルが自社の問い合わせで最も良い回答を出すとは限りません。自社データで客観的に比較すべきです。",["最も料金が高いモデルは品質も高い"]],"2":["一般的なランキングは汎用的なベンチマークの結果で、自社の質問での回答品質を保証しません。",["一般的なランキングで 1 位"]],"3":["1 名が数回試した印象は主観的でサンプルも少なく、客観的な比較になりません。",["担当者 1 名が数回試した印象"]]},"AIB-C01-104":{"0":["KPI の数を増やしても、確認して対応する責任者がいなければ同じ問題が残ります。かえって管理が難しくなります。",["KPI の数を 3 倍に増やす"]],"1":["年 1 回の監査では悪化に気付くのが遅れ、日常的な改善の行動につながりません。",["年に 1 回の監査に任せる"]],"3":["悪化した KPI を削除すると問題が見えなくなるだけで、改善にはつながりません。",["数値が悪化した KPI を削除する"]]},"AIB-C01-105":{"0":["人件費は変わっていないため、時間に時給を掛けた金額を削減額とすると実際の費用削減と混同し、効果を過大に見せます。",["そのままコスト削減額として計上する"]],"1":["利用者数は利用状況を示すだけで、削減した時間がどのような価値を生んだかを説明できません。",["利用者数だけを報告する"]],"3":["人件費が変わらなくても、削減した時間を付加価値業務に回したり増員を回避したりすれば価値があります。効果なしとは言えません。",["効果はなかったと結論付ける"]]},"AIB-C01-106":{"0":["導入直後は習熟のために一時的に生産性が下がりやすく、1 か月目だけで中止すると本来の効果を確認できません。",["すぐに中止する"]],"2":["処理件数の測定をやめると、習熟後に改善したかを客観的に確認できなくなります。",["処理件数の測定をやめ"]],"3":["評価期間を無期限に延ばすと、効果のない施策にも資源を使い続けることになります。途中経過の指標で判断すべきです。",["無期限に延長する"]]},"AIB-C01-107":{"0":["従量課金でも、紙と PDF のデジタル化や統合、運用、教育の費用は発生します。利用料だけをコストにすると総コストを過小評価します。",["モデル利用料だけをコストとして計上し"]],"1":["70% の削減は実証されていないベンダーの数値で、最終確認が必須なことやデータ準備の費用も考慮されていません。効果を過大に見せます。",["ベンダーの説明どおり"]],"3":["法務担当者の最終確認は今後も必須で、削減時間をすべて人員削減とみなすのは非現実的です。最大値だけでは CFO の判断に耐えません。",["すべて人員削減として金額換算し"]]},"AIB-C01-108":{"0":["電話窓口の受付時間を短縮すると、顧客は解決できないまま困るだけで、顧客満足度がさらに下がります。根本原因の分析になりません。",["電話窓口の受付時間を短縮する"]],"2":["顧客満足度の低下と再問い合わせの増加は、未解決の離脱を成功と数えている可能性を示します。KPI の改善だけで成功とは言えません。",["施策は成功と報告する"]],"3":["調査を中止すると品質の悪化が見えなくなるだけです。補完指標の悪化は KPI の定義を見直すべきサインです。",["調査を中止する"]]},"AIB-C01-109":{"0":["成績のよい支店だけの結果を全社の効果とすると偏りが生じ、効果を過大評価します。",["最も成績のよい支店だけの結果"]],"2":["同時導入して前年平均と比べるだけでは、景気や季節などの外部要因を除けず、AI の効果を切り分けられません。",["導入前年の全社平均と比較する"]],"3":["利用状況だけでは業務成果を示せません。導入時期をずらせば比較群を確保して効果を測れます。",["効果測定をあきらめ"]]},"AIB-C01-110":{"0":["熱心な利用者数名の感想は偏りがあり、全社の効果を代表しません。取締役会への根拠として信頼性に欠けます。",["熱心な利用者数名の感想だけ"]],"1":["全社員が 1 日 1 時間削減できるという前提に根拠がなく、最大値を示すと過大評価として信頼を損ないます。",["1 日 1 時間の削減を掛けた最大値"]],"3":["直接測定できなくても、抽出調査やログを組み合わせた推計で説明できます。説明を放棄すると投資の妥当性を示せません。",["ROI は説明できないと回答する"]]},"AIB-C01-111":{"0":["最新のモデルへの切り替えは競合も同じように実行でき、持続的な差別化になりません。",["最新の基盤モデルに切り替え続ける"]],"2":["パラメータ数の大きいモデルは誰でも選べるため、競合との差別化の源泉になりません。",["最もパラメータ数の大きい基盤モデル"]],"3":["ライセンスの配布は競合もすぐに実行でき、それだけでは競争優位につながりません。",["ライセンスを全社員に配布する"]]},"AIB-C01-112":{"0":["データ量が増えても AI の利用料が無料に近づくことはありません。データフライホイールの価値は改善の好循環にあります。",["利用料が無料に近づく"]],"1":["データフライホイールは改善を回し続けることが前提で、一度集めれば改善不要になるという説明は逆です。",["改善の必要がなくなる"]],"3":["データフライホイールは自社サービスの利用から得たデータで回るもので、競合他社のデータを自由に使えるようになるわけではありません。",["競合他社のデータを自由に使える"]]},"AIB-C01-113":{"0":["自社顧客の利用履歴は自社だけが持つデータで、それに基づく提案は模倣されにくく差別化につながります。",["自社顧客の利用履歴に基づく"]],"2":["自社独自の業務ノウハウを組み込んだアシスタントは他社が再現しにくく、差別化につながる施策です。",["自社独自の業務ノウハウを組み込んだ"]],"3":["自社だけが持つ長年の保守記録は独自のデータ資産で、それを使った故障診断は差別化につながります。",["自社だけが持つ長年の保守記録"]]},"AIB-C01-114":{"0":["Amazon Polly はテキストを音声に変換するサービスで、閲覧・購入履歴に基づく商品のおすすめはできません。",["Amazon Polly"]],"1":["AWS Glue はデータの抽出・変換・ロード（ETL）を行うサービスで、パーソナライズされたおすすめを提供する機能はありません。",["AWS Glue"]],"3":["Amazon Textract は文書から文字や表を抽出するサービスで、顧客ごとの商品推薦はできません。",["Amazon Textract"]]},"AIB-C01-115":{"0":["モデル名を伏せても、同じようなサービスは他社も作れます。秘匿だけでは長期的な優位を保てません。",["基盤モデルの名前を公開しない"]],"2":["仕様を変えずにいると、改善を続ける後発企業に追い抜かれます。生成 AI のサービスは模倣されやすいため改善の継続が必要です。",["仕様を変えずに維持する"]],"3":["最初に発表したという事実は長く続く優位にならず、広告で繰り返してもサービスの価値は高まりません。",["最初に発表したという事実を広告で"]]},"AIB-C01-116":{"1":["Bedrock Guardrails は有害な内容のフィルタリングなどの安全対策の機能で、自社の技術資料を検索して回答に反映する役割はありません。",["Amazon Bedrock Guardrails"]],"2":["AWS Cost Explorer は利用料金を分析するツールで、技術資料を回答に反映する RAG の機能はありません。",["AWS Cost Explorer"]],"3":["モデル評価は候補モデルの品質を比較する機能で、自社資料を検索して回答の根拠に使う仕組みではありません。",["Amazon Bedrock のモデル評価"]]},"AIB-C01-117":{"0":["問い合わせ対応での人件費削減はコスト削減で、稼働データを生かした新たな収益源にはなりません。",["サポート部門の人件費を減らす"]],"1":["稼働データを第三者に一括売却すると、顧客の信頼や契約上の問題を招くおそれがあり、継続的な収益にもなりません。",["第三者のデータ販売業者に一括で売却する"]],"3":["製造工程の効率化と値下げはコスト面の取り組みで、稼働データと AI を組み合わせた新しい収益源にはなりません。",["機器の販売価格を下げる"]]},"AIB-C01-118":{"0":["1 つのモデルに利用条件を固定すると、性能や価格の良い新しいモデルへ切り替えられず、かえって競争力を損ないます。",["特定の 1 つの基盤モデルと長期契約を結び"]],"1":["先行者であることは他社がすぐに追随でき、ブランドだけでは長期的な優位を保てません。",["先行者としてのブランドを確立する"]],"2":["価格の引き下げは競合も追随しやすく、改善を続ける組織能力のような持続的な優位にはなりません。",["すべて価格の引き下げに充てる"]]},"AIB-C01-119":{"1":["顧客は新しいアプリの導入に消極的なため、乗り換えを求めると利用が定着せず、体験の改善につながりません。",["顧客に乗り換えを求める"]],"2":["広告で強調するだけでは、修理依頼の体験そのものは改善されず差別化になりません。",["広告で強調するだけ"]],"3":["顧客が使っていないチャネルに AI を置いても利用されず、主な接点である既存アプリの体験は変わりません。",["顧客が使っていない新しい SNS チャネル"]]},"AIB-C01-120":{"1":["競合他社が販売データを提供することは通常なく、待っていても予測精度は向上しません。",["競合他社の販売データを入手できるまで待つ"]],"2":["モデルを最新版にしても、店頭の売れ行きが分からないというデータの不足は解消されません。",["最新版に置き換えることだけに投資する"]],"3":["公開ニュースは誰でも入手でき差別化にならず、店頭の売れ行きのデータも得られません。",["公開されているニュース記事だけ"]]},"AIB-C01-121":{"0":["汎用チャット画面は他社もすぐに提供でき、会計事務所の業務に特化した価値にもなりません。",["汎用チャット画面を追加し"]],"1":["同じ機能を 1 か月早く出しても、すぐに模倣されて差はなくなります。持続的な差別化になりません。",["1 か月早く同じ機能を出す"]],"2":["対応言語の数は他社も追随しやすく、会計実務に特化した価値を生みません。",["対応する言語の数を増やす"]]},"AIB-C01-122":{"0":["1 つのモデルに全機能を固定すると、性能や価格の良いモデルが出ても切り替えられず、競争力を保てません。",["1 つのモデルに全機能を固定する"]],"2":["モデルの更新を評価せずに使い続けると、品質の変化や他の選択肢の優位に気付けません。",["評価せずに使い続ける"]],"3":["短期間で性能と価格が変わる中で年 1 回だけの選定に固定すると、変化に素早く対応できません。",["年に 1 回だけ行う"]]},"AIB-C01-123":{"0":["価格の一律引き下げは既存の請負事業の話で、新たな収益源にはならず利益も減ります。",["価格を一律に引き下げる"]],"1":["データを活用しなければ、独自データという資産から新しい価値も収益も生まれません。",["活用しない"]],"3":["担当部署の廃止は新規事業の創出につながらず、データを蓄積・活用する体制も失われます。",["担当部署を廃止する"]]},"AIB-C01-124":{"0":["汎用的な文章校正ツールは市販品で十分で、自作しても差別化にはなりません。",["汎用的な文章校正ツールを自作する"]],"1":["データセンターの管理は AWS などのクラウドに任せられ、生成 AI による差別化の源泉にはなりません。",["データセンターの建物を管理する"]],"3":["基盤モデルの一からの事前学習は多くの企業にとって過剰な投資で、マネージドなモデルを使えば済むため差別化になりません。",["一から事前学習する"]]},"AIB-C01-125":{"1":["長いプロンプトはすでに試して表現の一貫性が不十分でした。書き込みを増やしてもトークンのコストが増えるだけで安定しにくい方法です。",["より長いプロンプト"]],"2":["人手に戻すと、自社が持つ大量の校閲済み文書を生かせず、生成 AI による効率化の機会も失います。",["すべて人手で作成する"]],"3":["基盤モデルを一から開発するのは膨大なコストと期間がかかり過剰です。既存モデルのファインチューニングで十分です。",["基盤モデルを一から開発する"]]},"AIB-C01-126":{"0":["パンフレットを増やしても、顧客の要望に応じた旅程の提案や空き状況の確認、予約手配を自動で一貫して進めることはできず、差別化になりません。",["AI は使わず"]],"1":["定型回答のチャットボットは決まった質問に答えるだけで、空き確認や予約などの複数の手順を自律的に進めることはできません。",["定型回答だけを返す"]],"3":["提案文の生成だけでは予約まで一貫して支援できません。顧客に別窓口での手続きを強いるため、問題文の求める一貫した体験になりません。",["提案文だけを生成し","別の窓口で行ってもらう"]]},"AIB-C01-127":{"0":["機能では勝てなくても、地域の顧客との信頼関係という強みを AI 体験に生かせば差別化できます。検討の中止は機会を捨てる判断です。",["検討を中止する"]],"1":["担当者を廃止すると、自行の強みである顧客との長い関係と信頼を手放すことになります。コスト競争では大手やフィンテックに勝てません。",["人の担当者を廃止し","コストで勝負する"]],"2":["機能の豊富さでは勝てないと分かっているのに大手を追随しても差別化になりません。引き継ぎを後回しにすると信頼という強みも生かせません。",["すべて揃えることを最優先","後回しにする"]]},"AIB-C01-128":{"0":["プレスリリースの回数は広報活動にすぎず、AI の能力や業務上の優位を生みません。競合もすぐに同じことができます。",["プレスリリースの回数"]],"3":["最新の基盤モデルは誰でも利用できるため、早く採用しても競合はすぐ追いつけます。1 年以上続く持続的な優位にはなりません。",["他社より早く採用"]],"4":["一般的なチャットツールは競合も同じように配布できるため、模倣が容易で持続的な優位にはつながりません。",["一般的な AI チャットツール"]]},"AIB-C01-129":{"0":["独自の生産データは差別化の源泉です。競合にも販売されるモデルの学習に使われると、自社の優位が失われるおそれがあります。",["データの価値はない","どのような条件でも"]],"2":["取引の全面禁止は極端で、AI ベンダーとの有益な協業の機会まで失います。条件を確認してリスクと便益を比較すべきです。",["取引自体を全社で禁止"]],"3":["無償でも、データの利用範囲や権利を確認せずに提供すると、競合の能力向上に使われて自社の優位を失うリスクがあります。",["条件を確認せずに直ちに提供"]]},"AIB-C01-130":{"0":["独自の会員データを使う②こそ他社が真似できない差別化の源泉です。そこに投資しないと差別化を重視する方針に反します。",["②には投資せず"]],"2":["汎用的な①③まで自社で一から開発すると、既製品で安く済む部分にも費用がかかり、限られた予算でコストを抑えられません。",["すべてを自社で一から開発"]],"3":["議事録作成は一般的な業務で既製品で十分です。差別化にならない用途に最大の予算を投じるのは非効率です。",["③に最も多くの予算"]]},"AIB-C01-131":{"1":["尋ねられたときだけの開示では、多くの顧客は AI と対話していると気付けません。透明性には最初から明示することが必要です。",["尋ねられた場合にのみ"]],"2":["担当者の名前で表示して人が対応しているように見せるのは顧客を欺く行為で、透明性に真っ向から反し信頼を損ないます。",["担当者の名前で表示し","人が対応しているように見せる"]],"3":["利用規約の中だけに記載しても顧客は自然に認識できません。対話の画面で分かりやすく開示しなければ透明性を確保できません。",["利用規約の中にのみ記載"]]},"AIB-C01-132":{"1":["各部門が自部門の案件を審査すると、基準が部門ごとにばらつき、利害関係から客観的な審査も難しくなります。",["自部門の案件をそれぞれ審査"]],"2":["AI のリスクは技術だけでなく法務や業務にもまたがります。IT 部門だけでは法令や事業上の観点が欠けて審査が偏ります。",["IT 部門だけで構成"]],"3":["法務単独では、セキュリティやデータ、業務への影響といった技術・事業面の観点が欠け、全社方針の策定や審査には不十分です。",["法務部門が単独で"]]},"AIB-C01-133":{"0":["システムプロンプトの指示だけでは、巧妙な入力で回避されることがあり、個人情報の出力も確実には防げません。",["書くことだけで対応する"]],"1":["Amazon Macie は S3 に保存されたデータの機密情報を検出するサービスで、生成 AI アプリの入出力を制御する機能はありません。",["Amazon Macie","出力の制御を任せる"]],"3":["AWS CloudTrail は API 呼び出しを記録して監査に使うサービスで、モデルの出力内容をフィルタリングして防ぐことはできません。",["AWS CloudTrail","不適切な出力を防ぐ"]]},"AIB-C01-134":{"0":["Trusted Advisor のコスト最適化チェックは未使用リソースなどの費用削減を提案するもので、公平性や透明性など責任ある AI の評価には使えません。",["コスト最適化チェック"]],"1":["AWS Artifact は AWS 自身の認証やコンプライアンスレポートを入手するサービスで、自社の AI ワークロードを責任ある AI の観点で評価する枠組みではありません。",["AWS Artifact"]],"3":["AWS Pricing Calculator は利用料金を見積もるツールで、AI システムの公平性や透明性を評価する機能はありません。",["AWS Pricing Calculator"]]},"AIB-C01-135":{"0":["精度のために属性情報を多く含めるのはデータ最小化の原則に反し、漏えい時の被害やプライバシーのリスクを増やします。",["できるだけ多く含める"]],"1":["別用途のために取得できる個人データをすべて送るのは、目的外利用につながりデータ最小化の原則に反します。",["別の用途に使えるよう","すべて送っておく"]],"3":["暗号化は送信時の保護にすぎず、必要以上の個人データを扱うこと自体のリスクは減りません。量の制限は依然として必要です。",["量に制限は設けない"]]},"AIB-C01-136":{"0":["利用ポリシーはルールを定めるもので、利用料金とは関係がありません。料金を無料にする効果はありません。",["利用料金を無料にする"]],"1":["全員に開放する前提で、活用を促しつつリスクを抑えるのがポリシーの目的です。全面禁止は開放の方針と矛盾します。",["全面的に禁止する"]],"3":["利用ポリシーは入力してよい情報や禁止用途を定めるもので、業務時間を一律に短くするための規則ではありません。",["業務時間を一律に短くする"]]},"AIB-C01-137":{"1":["エッジ AI は端末側で推論する構成を指す言葉で、承認されていない AI サービスの無断利用を表すものではありません。",["エッジ AI"]],"2":["説明可能な AI は判断の根拠を示す技術を指します。無断利用はむしろ管理が及ばず透明性が下がる状況です。",["説明可能な AI"]],"3":["転移学習は学習済みモデルを別のタスクに流用する手法で、社員が未承認サービスに資料を入力する状況とは無関係です。",["転移学習"]]},"AIB-C01-138":{"0":["利用状況を一覧にしても料金が自動的に下がるわけではありません。台帳の目的はリスクの所在を把握することです。",["自動的に下がる"]],"1":["一覧化は管理のための可視化で、AI モデルの精度には影響しません。精度の向上には評価や改善の取り組みが別に必要です。",["精度が自動的に向上する"]],"2":["利用状況の台帳を作っても AI の処理速度は変わりません。ガバナンスの取り組みと性能は別の話です。",["処理速度が上がる"]]},"AIB-C01-139":{"1":["低リスク案件まで同じ厳格な審査を課すと審査の負荷が膨らみ、活用が遅れてシャドー AI を招きます。負荷の適切な配分になりません。",["すべての案件に高リスク案件と同じ"]],"2":["予算規模とリスクの大きさは一致しません。少額でも人事評価など影響の大きい用途を審査から漏らしてしまいます。",["予算規模の大きい案件だけ"]],"3":["社内向けでも人事評価のように個人に大きく影響する用途があります。社外公開の有無だけで判断すると高リスク案件を見落とします。",["社内向けの案件はすべて審査を省略"]]},"AIB-C01-140":{"0":["精度が上がるかどうかは利用してよいかの根拠になりません。まず目的や同意など法令・規程への適合を確認すべきです。",["精度がどの程度上がるか"]],"1":["暗号化は重要な保護策ですが、そもそも個人データをその目的で使ってよいかという適法性の確認が先です。",["暗号化して保存できる"]],"2":["他社が利用しているかどうかは自社の利用が適法かの根拠になりません。目的・同意・保管場所の法令適合を確認すべきです。",["同業他社が同様のデータ"]]},"AIB-C01-141":{"0":["「AI 生成」と表示しても、既存の著作物に類似していれば権利侵害のリスクはなくなりません。類似性の確認が必要です。",["「AI 生成」と表示すれば"]],"1":["プロンプトに他社名を含めなくても、生成物が既存の著作物や商標に似てしまうことはあり、権利の問題は生じ得ます。",["他社名を含めていなければ"]],"3":["有料プランで生成しても、既存作品との類似による侵害リスクは残ります。権利の帰属も規約次第で、確認なしの利用は危険です。",["確認せずに使う"]]},"AIB-C01-142":{"0":["担当者に見せなくても、脆弱な顧客を狙って広告を出し分けること自体が顧客に不利益を与えます。害は解消されません。",["システム内部だけで使う"]],"1":["データの出所が社内であっても、借金の悩みなどの弱みを推定して狙う用途は顧客を害するおそれがあり、責任ある AI の観点で問題です。",["社内の購買履歴だけ"]],"2":["規約に一般的な記載があっても、脆弱性を推定して狙い撃ちする用途まで顧客が想定しているとはいえず、害や信頼の損失は解消されません。",["利用規約に","記載済みであれば"]]},"AIB-C01-143":{"1":["利用者を匿名にすると、誤用が起きても誰が行ったか追跡できず、抑止や是正が難しくなります。",["利用者を匿名にし"]],"2":["経営層だけに限定すると誤用は減っても、社員が業務で活用する機会が失われ、社内公開の目的を果たせません。",["経営層だけに限定"]],"3":["利用ログを一切取らないと、不適切な利用を発見・調査できません。誤用への備えとして監視は必要です。",["利用ログを一切取得しない"]]},"AIB-C01-144":{"0":["社内報の見出し案は人が確認して選ぶもので、誤りがあっても個人の権利や機会への影響は小さく、低リスクの用途です。",["社内報の見出し案"]],"1":["誤字の検出は誤りがあっても影響が限定的で、個人の機会や権利を左右しない低リスクの用途です。",["誤字を検出する"]],"3":["会議室の予約検索は個人に重大な影響を与える判断ではなく、厳格な審査が必要な高リスク用途には当たりません。",["会議室の予約状況"]]},"AIB-C01-145":{"0":["EU AI 法は EU 域内で提供・利用される AI に適用され、規制の有無は開発国ではなく用途のリスクで決まります。",["開発国によって"]],"1":["規制の強さは利用料金ではなく、AI の用途がもたらすリスクの大きさによって決まります。",["利用料金の大きさ"]],"2":["EU AI 法はすべてを禁止するのではなく、許容できないリスクの用途のみを禁止し、他はリスクに応じた義務を課します。",["一律に禁止する"]]},"AIB-C01-146":{"0":["外部サービスによっては入力データが学習に使われたり保管されたりします。個人情報や取引条件を自由に入力すると漏えいのリスクがあります。",["どの外部サービスでも自由に"]],"1":["元の記録を削除しても、外部サービスに入力したデータの扱いは変わりません。学習や保管によるリスクは残ります。",["元の商談記録を削除すれば"]],"2":["一律禁止では、データの扱いを確認できる安全なサービスでの活用まで妨げられ、活用とリスク管理の両立ができません。",["一律に禁止する"]]},"AIB-C01-147":{"0":["Amazon Bedrock では料金の多少にかかわらず、入出力データが基盤モデルの学習に使われることはありません。",["料金を多く払った場合のみ"]],"1":["データの取り扱いは方針として定められており、ランダムに決まることはありません。入出力は学習に使われません。",["毎回ランダムに決まる"]],"3":["Amazon Bedrock では入出力データがモデル提供者と共有されたり、学習に使われたりすることはなく、記述は逆です。",["モデル提供者に送られ","学習に使われる"]]},"AIB-C01-148":{"0":["AWS Pricing Calculator は料金を見積もるツールで、誰がいつどの操作をしたかを記録する機能はありません。",["AWS Pricing Calculator"]],"2":["Amazon Polly はテキストを音声に変換するサービスで、API 操作の履歴の記録や監査には使えません。",["Amazon Polly"]],"3":["Amazon Translate は機械翻訳サービスで、操作の記録を取る機能はなく監査要件を満たせません。",["Amazon Translate"]]},"AIB-C01-149":{"0":["審査を全廃すると、規制当局が求める高リスク用途の管理ができなくなります。スピードと管理の両立になりません。",["審査を全廃し"]],"2":["審査をさらに厳しくすると承認がもっと遅れ、現場の不満とシャドー AI の利用がかえって増えます。処分では根本原因を解決できません。",["さらに厳しくし","処分する"]],"3":["全面停止は極端で、規制当局が求めるのは高リスク用途の管理であり、低リスクの活用まで止める必要はありません。",["全面的に停止する"]]},"AIB-C01-150":{"0":["規制を待つだけでは、すでに存在するリスクを管理できず、全社で一貫した仕組みも作れません。",["何もしない"]],"1":["最も緩い基準に合わせると、規制の厳しい国の要件を満たせず違反のリスクがあります。",["最も規制の緩い国の基準だけ"]],"3":["国ごとに無関係なルールで本社が把握しないと、全社での一貫性が失われ、リスクの全体像も管理できません。",["本社では把握しない"]]},"AIB-C01-151":{"1":["サーバーの設置場所は遅延やデータ所在地に関係しますが、判定が特定集団に偏る原因にはなりません。",["サーバーの設置場所"]],"2":["画面の色は見た目の設定で、モデルの判定内容には影響せず、バイアスの原因にはなりません。",["画面の色の設定"]],"3":["パスワードの長さは認証のセキュリティに関係するもので、モデルの判定の偏りとは無関係です。",["パスワードの長さ"]]},"AIB-C01-152":{"1":["データ件数の多さ自体は偏りの原因ではありません。性別と相関する別の項目が残っていることが問題です。",["件数が多すぎる"]],"2":["性別の項目を除外しても AI が誤作動するわけではありません。偏りは代理変数を通じて残ります。",["必ず誤作動する"]],"3":["画面の表示はモデルの判定に影響しません。判定に使われる特徴量に性別と相関する項目があることが原因です。",["画面に性別が表示"]]},"AIB-C01-153":{"1":["全体の正解率が高くても、特定の集団だけ誤りが多いことがあります。属性別に比較しないと公平性は確認できません。",["全体の正解率だけ"]],"2":["開発者の主観では公平性を客観的に評価できません。属性ごとの承認率などの指標で確認する必要があります。",["公平だと思うかを尋ねる"]],"3":["審査件数の合計は処理量を示すだけで、属性間で結果に不当な差があるかは分かりません。",["審査件数の合計だけ"]]},"AIB-C01-154":{"0":["過学習は学習データに適合しすぎて汎化性能が落ちる現象で、属性間の承認率の差を評価する考え方ではありません。",["過学習"]],"2":["再現率は陽性をどれだけ見つけられたかを示す性能指標で、属性ごとの承認割合の同等性を表す公平性の考え方ではありません。",["再現率"]],"3":["データドリフトは入力分布の変化による性能低下の原因で、属性間の結果の差を直接評価するものではありません。",["データドリフト"]]},"AIB-C01-155":{"0":["レイテンシーは応答の遅さを指す性能の問題で、生成画像の性別や人種の偏りとは関係ありません。",["レイテンシーの増加"]],"1":["過学習は学習データに適合しすぎて新しいデータで性能が落ちる現象で、社会的な固定観念の再生産を表す言葉ではありません。",["過学習"]],"3":["プロンプトインジェクションは悪意ある入力でモデルの指示を乗っ取る攻撃で、学習データ由来の偏りとは別の問題です。",["プロンプトインジェクション"]]},"AIB-C01-156":{"0":["地域の項目を削除しても、郵便番号など相関する代理変数で偏りが残ることがあります。原因を分析せず運用を続けるのは危険です。",["地域の項目を削除し","運用を続ける"]],"2":["原因を分析しないまま一律に加点すると、別の不公平を生むおそれがあり、根本的な是正になりません。",["一律で加点する補正"]],"3":["全体の承認率が範囲内でも、特定地域への不利な判定は続きます。影響が大きい公平性の問題を放置することになります。",["現行のまま運用を続ける"]]},"AIB-C01-157":{"0":["全体の正解率が維持されていても、特定の集団の結果だけが悪化することがあります。全体の指標だけでは偏りを見逃します。",["全体の正解率を毎月監視し"]],"1":["データは時間とともに変化するため、稼働前に合格していても後からバイアスが生じます。継続的な確認が必要です。",["確認は不要とする"]],"2":["年 1 回の確認では、偏りが生じてから発見までに時間がかかり、その間に顧客への不利益が続きます。",["年 1 回の内部監査"]]},"AIB-C01-158":{"1":["運用中もデータの変化でバイアスは後から生じます。開発時の確認だけでは、本番での偏りを発見できません。",["運用中は確認しない"]],"2":["測定しても誰にも報告しなければ、問題が見つかっても対応につながりません。報告先と対応手順を決めて初めて監視が機能します。",["誰にも報告しない"]],"3":["指摘を待つだけでは発見が遅れ、気付かれない偏りは放置されます。定期的な測定による能動的な監視が必要です。",["指摘された場合にのみ調査"]]},"AIB-C01-159":{"0":["名前を変えてもモデルの中身は変わらず、顧客構成の変化による予測精度の低下は解消されません。",["名前を変更する"]],"1":["若年層を対象外にして報告しないのは問題の隠蔽で、データドリフトという原因にも対処できず、説明責任にも反します。",["予測の対象から外し","報告しない"]],"3":["新プランの開始で顧客構成が変わっており、一時的とはいえません。データドリフトを放置すると誤った予測が続きます。",["そのまま使い続ける"]]},"AIB-C01-160":{"0":["同じデータを複製しても件数が増えるだけで、地方店舗や多様な客層の代表性は改善されません。",["同じデータを複製する"]],"1":["都市部だけのデータでは地方の客層を代表できず、地方店舗で性能が落ちることが予想できます。問題が出てからでは対応が遅れます。",["問題が出てから考える"]],"2":["地方導入の計画を伏せても、データの代表性の問題は解決しません。透明性にも反し、公平性への対応になりません。",["伏せて計画を進める"]]},"AIB-C01-161":{"0":["奨学金の選考は個人の機会に大きく影響するため、公平性の評価をやめると偏った選考を見逃し、説明責任も果たせません。",["公平性の評価をやめ"]],"2":["計算のしやすさは定義を選ぶ根拠になりません。どの公平性を重視するかは事業目的や法令、関係者の合意で決めるべきです。",["最も計算しやすい定義"]],"3":["定義を決めないまま開発すると、何をもって公平とするかの基準がなく、評価も説明もできません。",["定義を決めずに"]]},"AIB-C01-162":{"0":["生成 AI の偏りは職種や条件によって現れるため、1 件だけの確認では不適切な表現を見逃します。",["1 件だけ生成して"]],"1":["応募者の指摘を待つと、公開後に差別的な表現が広まってしまい、公開前に確認するという要件を満たせません。",["応募者からの指摘に任せる"]],"3":["生成 AI は学習データの偏りを反映するため中立とはいえません。確認を省くと差別的な表現が公開されるおそれがあります。",["中立なので確認は不要"]]},"AIB-C01-163":{"0":["Amazon EBS は EC2 用のブロックストレージで、基盤モデルの正確さや有害性を比較評価する機能はありません。",["Amazon EBS"]],"2":["AWS Cost Explorer は利用料金の分析ツールで、モデルの回答品質や偏りを比較する機能はありません。",["AWS Cost Explorer"]],"3":["AWS Direct Connect はオンプレミスと AWS を専用線で接続するサービスで、モデル評価とは無関係です。",["AWS Direct Connect"]]},"AIB-C01-164":{"0":["全社で使われている以上、半年待つ間にも不公平な配置判断が積み重なります。影響の把握と是正を先送りすべきではありません。",["半年後の定期点検"]],"2":["記録を削除して隠すのは不誠実で、代理変数による偏りも残り得ます。影響の把握や是正もできなくなります。",["問題を隠す"]],"3":["社員に見えなくても、不公平な推薦で重要案件の機会を奪われる不利益は続きます。放置は責任ある判断ではありません。",["そのまま使い続ける"]]},"AIB-C01-165":{"0":["手続きなしで偏りのあるモデルに戻すと、顧客や法令、評判上のリスクが検討されず、ガバナンスが機能しません。",["手続きなしで切り替える"]],"2":["指標を測らなければ偏りの有無を把握できず、リスクを見えなくするだけで問題は解決しません。",["測定しないことにする"]],"3":["精度だけで判断すると、偏りによる顧客への不利益や法令違反のリスクを無視することになります。常に精度が優先とはいえません。",["常に正しい"]]},"AIB-C01-166":{"0":["全体の平均値だけでは、高齢者など特定の年齢層で認識精度が低いことを見逃します。",["全体の平均値だけ"]],"2":["テストを省略すると、高齢者の発話を聞き取れないといった偏りを公開前に発見できません。",["テストを省略して"]],"3":["20〜30 代の開発チームの声だけでは、高齢者特有の話し方による精度低下に気付けず、偏りを見落とします。",["開発チームの声だけ"]]},"AIB-C01-167":{"0":["データは変化するため、導入時 1 回の確認では後から生じる偏りを発見できません。苦情を待つ方式では支援の遅れが生じます。",["1 回だけ公平性を確認し"]],"2":["処理件数や処理時間は効率の指標で、地域や年齢、国籍による偏りや誤った低優先判定は把握できません。",["処理件数と平均処理時間だけ"]],"3":["属性情報を記録しないと、属性別の誤り方を測定できず、偏りの有無を検証できません。説明責任も果たせません。",["属性情報を一切記録せず"]]},"AIB-C01-168":{"0":["過去の実績は当時の社会的な偏りを含んでおり、それを再現することは正しくありません。偏りの再生産を放置することになります。",["正しいと説明する"]],"2":["注意書きを表示しても表示される求人の偏りは変わりません。学習データという根本原因に対処していません。",["注意書きを表示する"]],"3":["モデルを大きくしても偏ったデータを学習すれば偏りは再現されます。自然に消えることはありません。",["より大きなモデルに替える"]]},"AIB-C01-169":{"0":["ベンダーの検証は自社の高齢者比率の高い顧客層で行われたとは限りません。自社データで検証せずに導入すると偏りを見逃します。",["そのまま導入する"]],"1":["購入した AI でも、利用する企業は自社の顧客に対する公平性に責任を負います。ベンダー任せにはできません。",["自社は対応不要"]],"3":["高齢者を対象から外すと、自社の主要な顧客層を不利に扱うことになり、別の不公平を生みます。",["高齢者の顧客をスコアリングの対象から外して"]]},"AIB-C01-170":{"0":["努力を示しても対策の効果は分かりません。経営判断には地域別の精度の変化という客観的な結果が必要です。",["努力したことを示す"]],"2":["追加したデータの件数は投入量にすぎず、方言の強い利用者の精度がどれだけ改善したかという効果を示せません。",["データの件数だけ"]],"3":["全体の平均精度が上がっても、方言地域との差が縮まったとは限りません。地域別に比較しないと公平性の効果は分かりません。",["全体の平均精度"]]},"AIB-C01-171":{"2":["開発者の個人名と連絡先は公平性の説明に不要で、個人のプライバシーや安全上の問題も生じます。",["開発者の個人名と連絡先"]],"3":["不利な結果を伏せて良い結果だけを示すのは不誠実で、発覚すれば顧客や規制当局の信頼を大きく損ないます。",["良い結果だけ"]],"4":["全パラメータの数値を示しても、顧客や規制当局には理解できず、公平性の説明として役立ちません。",["全パラメータの数値"]]},"AIB-C01-172":{"1":["AI の判定を医師より優先すると、AI の誤りがそのまま診断に反映されます。診断の最終責任は医師が持つべきです。",["AI の判定を優先する"]],"2":["月 1 回の抜き取り確認は事後の点検で、確認前に誤った判定が診療に使われてしまいます。",["月に 1 回","抜き取りで確認"]],"3":["信頼度が高くても誤りはあり得ます。確定診断を AI に任せると、重大な判断から医師の関与が外れてしまいます。",["そのまま確定診断とし"]]},"AIB-C01-173":{"0":["プロンプトエンジニアリングはモデルへの指示文を工夫する技術で、人による監督の形態を指す言葉ではありません。",["プロンプトエンジニアリング"]],"1":["Human-in-the-loop は個々の判断に人が関与して承認する形態です。全件を確認せず監視と介入を行う形態とは異なります。",["Human-in-the-loop"]],"3":["ファインチューニングは追加データでモデルを調整する手法で、運用時の人による監督の形態ではありません。",["ファインチューニング"]]},"AIB-C01-174":{"0":["利用者の報告任せでは、誤った結果が登録・公開されてから見つかることになり、自信のない結果を事前に確認できません。",["誤りに気付いた人が報告する"]],"2":["月末の抜き取りは事後の傾向確認で、自信のない個々の結果を登録前に確認する仕組みになりません。",["月末にまとめて","抜き取り"]],"3":["全件確認では、自信のないものだけに絞るという要件に反し、担当者の負荷とコストが大きくなります。",["すべての抽出結果を担当者が 1 件ずつ確認"]]},"AIB-C01-175":{"0":["データドリフトは入力データの分布が変化する現象で、人が AI の提案を過信する傾向を指す言葉ではありません。",["データドリフト"]],"2":["プロンプトインジェクションは悪意ある入力でモデルを操る攻撃で、確認担当者の心理的な傾向とは無関係です。",["プロンプトインジェクション"]],"3":["選択バイアスはデータの集め方が偏ることで生じる偏りで、AI の判断を過信して承認する傾向ではありません。",["選択バイアス"]]},"AIB-C01-176":{"0":["問題を顧客に知らせない方法を決めるのは透明性に反し、発覚すれば信頼を大きく損ないます。",["顧客に知らせない方法"]],"1":["名称を変えても不適切な回答は止まりません。被害を抑えるには停止や切り替えの手順が必要です。",["名称の変更手順"]],"2":["広告の出稿計画は不適切な回答への対応と無関係で、問題発生時の被害拡大を防げません。",["新しい広告の出稿計画"]]},"AIB-C01-177":{"0":["人による判断の過程を記録しないと、誰がどのような理由で最終判断したかを後から検証できません。",["人による判断の過程は記録しない"]],"1":["結果と日付だけでは、どの入力とモデルに基づいて判断したかが分からず、経緯を検証できません。",["判断結果と判断日だけ"]],"2":["開発時の評価レポートはモデル全体の性能を示すだけで、個々の判断が何に基づいて行われたかは検証できません。",["個々の判断の記録は不要"]]},"AIB-C01-178":{"1":["免責表示を付けても、AI を使ってサービスを提供した企業の責任が一切なくなるわけではありません。",["一切の責任を負わない"]],"2":["責任共有モデルでは、AI の出力をどう使うかは顧客の責任です。出力内容の責任を AWS が負うわけではありません。",["責任は AWS が負う"]],"3":["モデルを業務に組み込み顧客に提供したのは企業であり、出力の利用と顧客への影響の責任はその企業が負います。",["モデルの提供者が"]]},"AIB-C01-179":{"0":["返金の可否判断は顧客の不利益に直結するため、人の確認なしでは誤判断を防げません。影響に応じた監督が必要です。",["どちらも人による確認は不要"]],"2":["影響の小さい説明文を全件承認し、影響の大きい返金判断を確認しないのは逆で、監督の配分が誤っています。",["②は確認しない"]],"3":["全件を 3 人で確認するとコストが過大で、影響の小さい説明文にまで過剰な監督をかけることになります。",["全件を担当者 3 人で確認"]]},"AIB-C01-180":{"1":["承認率が高いのは確認が形骸化している兆候かもしれず、工程を廃止すると誤った支払い判定を止める手段がなくなります。",["確認の工程を廃止する"]],"2":["人数を減らすと 1 人あたりの負荷が増え、確認はさらに形だけになります。形骸化の改善とは逆の対策です。",["人数を半分に減らす"]],"3":["判定案を見せずに承認させると、担当者は内容を確認できず、監督がまったく機能しなくなります。",["担当者に見せず"]]},"AIB-C01-181":{"0":["判定理由を記録しないと、誤判定を検証・是正できず、顧客への説明もできません。権利保護に逆行します。",["理由を社内でも記録しない"]],"1":["問い合わせを受け付けないと、誤った判定で回線を止められた顧客が是正を求められず、権利が守られません。",["問い合わせを受け付けない"]],"3":["解除できないと、誤判定で停止された顧客の回線を復旧できず、顧客に重大な不利益を与えます。",["解除できない仕組み"]]},"AIB-C01-182":{"0":["生活困窮や健康不安などの深刻な相談を AI だけで完結させると、適切な支援につながらず住民に大きな影響が出るおそれがあります。",["最後まで対応する"]],"2":["受け付けずに終了すると、支援を必要とする住民が行き場を失います。専門の窓口へ引き継ぐ仕組みが必要です。",["受け付けない旨を表示して終了"]],"3":["定型文だけでは個別の深刻な状況に対応できず、必要な支援につながりません。人への引き継ぎが必要です。",["定型文だけを返す"]]},"AIB-C01-183":{"0":["実績を確認せずに初日から全面自動化すると、誤発注などのリスクを抑えられません。段階的な拡大が必要です。",["初日からすべての発注を自動化"]],"1":["上限金額だけでは、上限内の誤発注を防げません。精度を確認せずに任せるのはリスクの管理として不十分です。",["精度を確認せず"]],"3":["自律性の範囲を決めないと、エージェントがどこまで発注できるかを統制できず、誤りの影響が無制限になります。",["自律性の範囲は決めず"]]},"AIB-C01-184":{"0":["担当者の判断を記録しないと、AI の指摘がどこで誤っていたかが分からず、改善に生かせません。",["担当者の判断は記録せず"]],"1":["不採用を不利に評価すると、担当者が AI の指摘を盲目的に採用するようになり、自動化バイアスを助長します。",["評価で不利にする"]],"3":["すべて採用させると担当者の判断が形骸化し、AI の誤った指摘もそのまま契約に反映されてしまいます。",["すべて採用するよう指示"]]},"AIB-C01-185":{"0":["確認をやめれば誤った数値が公開されるリスクはさらに高まります。原因である責任者の不在にも対処していません。",["公開前の確認をやめる"]],"1":["AI の出力を使って公開した責任は組織にあります。ベンダーに責任を求めても、確認体制の欠如という原因は残ります。",["AI ベンダーに責任を求めて"]],"3":["全面禁止は極端で、活用の機会を失います。原因は確認責任者が決まっていないことで、利用自体ではありません。",["全社で禁止する"]]},"AIB-C01-186":{"0":["人の確認を完全になくすと、不適切な投稿の見逃しや正当な投稿の誤削除を検知・是正できず、ブランドや出品者との関係を損ないます。",["完全になくす"]],"1":["全件を人が確認すると年間数億円のコストがかかり、コストを抑えるという要件を満たせません。",["全件を人が確認し"]],"3":["削除判定をすべて自動にすると、正当な投稿の誤削除による出品者の苦情を防げません。掲載判定の全件確認もコストが過大です。",["削除判定はすべて自動"]]},"AIB-C01-187":{"0":["注意喚起だけでは、30 秒しか確認できない多忙な状況という根本原因が変わらず、再発を防げません。",["注意喚起の文書を配るだけ"]],"2":["医師の確認をなくすと、薬の用量の誤りがそのまま確定し、患者の安全に重大なリスクが生じます。",["医師の確認なしで確定"]],"3":["問題を分析しないまま利用をやめても、確認がすり抜けた原因が分からず、改善の機会を失います。",["問題の分析は行わない"]]},"AIB-C01-188":{"1":["権限を広げると、エージェントが誤った判断をしたときの損失がさらに大きくなり、再発防止と逆行します。",["権限を広げ"]],"2":["今回の問題は週末に起きており、週末の監視をなくすと同様の異常を検知できなくなります。",["週末は監視を行わない"]],"4":["判断の記録を削除すると、なぜ予算を集中させたかを分析できず、原因究明や再発防止ができません。",["記録を削除する"]]},"AIB-C01-189":{"0":["評価結果を開示しないと、本人が不当な評価に異議を唱えられず、説明責任や信頼を損ないます。",["一切開示しない"]],"1":["申し立てを受け付けないと、根拠の記録もない評価の誤りを是正できず、派遣スタッフに不当な不利益が続きます。",["申し立てを受け付けず"]],"3":["AI を参考にした判断でも、最終的な責任は会社と担当者にあります。AI を理由に責任を否定することはできません。",["会社に責任はない"]]},"AIB-C01-190":{"0":["出勤日数は勤怠の情報にすぎず、担当者が AI の判断を実際に検証・修正しているかどうかは分かりません。",["出勤日数だけ"]],"3":["モデル名とリリース日はモデルの属性情報で、人による監督が実際に機能しているかを示す指標になりません。",["モデル名とリリース日だけ"]],"4":["利用料金の総額はコストの情報で、担当者が AI の判断を実質的に監督しているかは評価できません。",["利用料金の総額だけ"]]},"AIB-C01-191":{"0":["現状を把握する前にツールを配布すると順序が逆で、利用状況からはデータ基盤やガバナンスの不足を評価できません。",["全社員に生成 AI ツールを配布し"]],"2":["他社の施策を模倣しても自社の課題は分かりません。自社のデータや人材、ガバナンスの状況を評価するのが先です。",["同じ施策を順に導入する"]],"3":["システム構成だけの棚卸しでは技術面しか分からず、人材やプロセス、ガバナンスの不足を見落とします。",["IT 部門のシステム構成だけ"]]},"AIB-C01-192":{"1":["Generative AI Lens は生成 AI ワークロードの設計のベストプラクティスで、6 つの観点で組織能力を整理する枠組みではありません。",["Generative AI Lens"]],"2":["責任共有モデルは AWS と顧客のセキュリティの責任分担を示すもので、AI 導入に必要な組織能力の整理には使いません。",["責任共有モデル"]],"3":["Trusted Advisor は AWS リソースの設定やコストの改善を提案するツールで、組織能力を整理する枠組みではありません。",["AWS Trusted Advisor"]]},"AIB-C01-193":{"0":["調達担当者は製品やサービスの購買を担う役割で、データの定義や品質を日常的に管理する役割ではありません。",["調達担当者"]],"2":["外部監査人は独立した立場で定期的に監査する役割で、日常的なデータ管理や利用者対応は行いません。",["外部監査人"]],"3":["ネットワーク管理者は通信基盤を運用する役割で、業務部門の立場からデータの定義や品質基準を管理する役割ではありません。",["ネットワーク管理者"]]},"AIB-C01-194":{"0":["可用性はシステムやデータが必要なときに利用できるかを表す観点で、項目の欠損の有無を表すものではありません。",["可用性"]],"1":["適時性はデータが十分に新しいかを表す観点で、必要な項目が欠けずに入力されているかとは異なります。",["適時性"]],"2":["一意性は同じ対象が重複して登録されていないかを表す観点で、項目の欠損とは別の観点です。",["一意性"]]},"AIB-C01-195":{"0":["ヘルプデスクのチケットは問い合わせの管理に使うもので、データの所在や意味、責任者を一覧で探す仕組みではありません。",["ヘルプデスクのチケット"]],"1":["請求書は取引の記録で、社内データのメタデータを整理して検索できるようにする仕組みではありません。",["請求書"]],"2":["ファイアウォールは通信を制御するセキュリティの仕組みで、データの所在や意味を整理する機能はありません。",["ファイアウォール"]]},"AIB-C01-196":{"0":["セキュリティパースペクティブはデータやワークロードの保護を扱い、組織文化や人材育成は主な対象ではありません。",["セキュリティ（Security）"]],"1":["オペレーションパースペクティブはクラウドサービスの運用を扱い、文化や人材育成、組織構造の見直しは扱いません。",["オペレーション（Operations）"]],"2":["プラットフォームパースペクティブは技術基盤の構築を扱い、人と組織の変革は人材パースペクティブの領域です。",["プラットフォーム（Platform）"]]},"AIB-C01-197":{"0":["Amazon Personalize はレコメンデーションを作るサービスで、S3 内の個人情報を検出する機能はありません。",["Amazon Personalize"]],"1":["Amazon Polly はテキストを音声に変換するサービスで、機密データの検出には使えません。",["Amazon Polly"]],"2":["AWS Budgets は費用の予算超過を通知するサービスで、文書に含まれる個人情報は検出できません。",["AWS Budgets"]]},"AIB-C01-198":{"0":["匿名化は個人を特定できる情報を取り除く処理で、画像に良品・不良品の正解を付ける作業ではありません。",["データの匿名化"]],"1":["プロンプトのテンプレート化は生成 AI への指示文を定型化する工夫で、学習用の正解ラベルを付ける作業とは異なります。",["プロンプトのテンプレート化"]],"2":["推論は学習済みモデルで新しいデータを予測する処理で、学習前に正解を付ける作業ではありません。",["モデルの推論"]]},"AIB-C01-199":{"0":["データ基盤が未整備のまま全社規模の高度な活用を始めると、データ品質の問題で失敗しやすく、順序が逆です。",["全社規模の高度な AI 活用 → データ基盤整備"]],"2":["基盤とガバナンスを最後に回すと、全社展開後にデータ品質やリスク管理の問題が表面化します。",["全社展開 → データ基盤とガバナンスの整備"]],"3":["基盤もガバナンスもないまま全社展開を先に行うと、データの不備やリスクの管理不足が全社に広がります。",["全社展開 → データ基盤整備"]]},"AIB-C01-200":{"1":["利用者は回答の根拠となった規程の版を見抜けないことが多く、古い規程に基づく誤った対応を招きます。",["利用者が見抜けばよい"]],"2":["RAG の回答は参照する文書に左右されます。モデルを高性能にしても、古い版を参照すれば誤った回答になります。",["より高性能なモデルを選べば"]],"3":["古い版や下書きまで取り込むと、最新版と矛盾する内容が回答に混ざります。量より文書の質が重要です。",["すべての文書をそのまま取り込む"]]},"AIB-C01-201":{"0":["定義や ID の体系が異なるまま結合すると、別の顧客を同一とみなすなどして誤った分析結果になります。",["定義を揃えずに単純に結合"]],"1":["一方の部門のデータだけでは、営業と保守を組み合わせて解約予兆を分析するという目的を果たせません。",["一方の部門のデータだけ"]],"2":["AI は定義の違いを自動的に解消できません。誤って結合されたデータを学習すれば誤った結果を出します。",["自動的に解消される"]]},"AIB-C01-202":{"0":["本社の所在地は AI の準備状況と関係がなく、データや人材、ガバナンスの成熟度を示しません。",["本社の所在地"]],"2":["広告予算の増減は AI 導入の準備状況を示す指標ではなく、データや体制の整備状況は分かりません。",["広告予算が増えているか"]],"3":["パソコンのメーカーの統一は AI の活用能力と無関係で、準備状況の評価観点になりません。",["パソコンのメーカー"]]},"AIB-C01-203":{"0":["Amazon Polly はテキストを音声に変換するサービスで、データレイクのアクセス権限を管理する機能はありません。",["Amazon Polly"]],"1":["AWS Artifact は AWS のコンプライアンスレポートを入手するサービスで、データレイクの権限管理はできません。",["AWS Artifact"]],"2":["AWS Pricing Calculator は料金を見積もるツールで、部門ごとのデータの参照範囲を制御できません。",["AWS Pricing Calculator"]]},"AIB-C01-204":{"0":["顧客数の多さは利用の適法性と関係がありません。取得時の利用目的や同意の範囲に新しい用途が含まれるかを確認すべきです。",["100 万人を超えているか"]],"2":["保存期間が短くても、利用目的や同意の範囲外の用途に使えば問題になります。確認すべき要点ではありません。",["保存期間が 1 年未満"]],"3":["ファイル形式は技術的な扱いやすさの問題で、そのデータを新しい用途に使ってよいかの判断には関係しません。",["Excel 形式かどうか"]]},"AIB-C01-205":{"0":["標準がないまま実験を増やすと、重複やばらつきが広がるだけで、本番運用やスケールへの準備が進みません。",["標準を作らずに"]],"1":["実験を全面中止すると、得られた知見や成果を捨てることになります。成果の出たものを本番化へつなげるべきです。",["全面的に中止し"]],"3":["共通の基盤や標準がない段階で全面変革に進むと、基盤不足で失敗しやすく、段階を飛ばしています。",["全面的な変革をすぐに開始"]]},"AIB-C01-206":{"0":["問い合わせを受け付けないと顧客の不便が増すだけで、データの鮮度という根本原因は解決しません。",["受け付けないようにする"]],"2":["文章が流暢になっても参照する在庫情報が古いままでは、誤った回答は変わりません。",["流暢なモデルに切り替える"]],"3":["注意書きを表示しても回答の誤りは解消されず、顧客の苦情の原因である古いデータの問題が残ります。",["常に表示するだけ"]]},"AIB-C01-207":{"0":["施策ごとの個別抽出を続けると、手間とデータの不整合が増え、全社展開のたびに同じ作業を繰り返します。",["個別に作り続ける"]],"2":["施策を増やしても基盤は自然には整いません。むしろ個別抽出が増えて不整合が広がります。",["自然に整う"]],"3":["手作業の抽出は時間がかかりミスも生じやすく、再現性がないため全社規模の活用に耐えられません。",["すべて手作業で行う"]]},"AIB-C01-208":{"1":["専門家の採用を待つと評価が遅れ、AI 活用の着手も先送りになります。外部の支援で今すぐ評価できます。",["評価を延期する"]],"2":["関心の有無だけでは、データ基盤やガバナンス、人材のスキルなどの準備状況を客観的に評価できません。",["質問だけで判定する"]],"3":["評価せずに他社を模倣しても、自社の課題に合った施策になるとは限らず、失敗のリスクが高まります。",["評価を行わずに"]]},"AIB-C01-209":{"1":["基準を変えると前回の結果と比較できず、この 1 年でどれだけ前進したかを示せません。",["異なる新しい評価基準"]],"2":["前回の結果を再提出しても 1 年間の変化は分からず、取締役会の問いに答えられません。",["そのまま再提出する"]],"3":["プロジェクトの件数は活動量を示すだけで、データや人材、ガバナンスなど成熟度の変化は分かりません。",["件数だけを報告する"]]},"AIB-C01-210":{"0":["スキャン画像のままでは文字情報として検索・活用できず、生成 AI による保守支援に生かせません。",["スキャン画像のまま"]],"2":["20 年分の報告書には貴重な保守の知見が含まれています。廃棄すると取り戻せないデータ資産を失います。",["すべて廃棄し"]],"3":["作業報告書には過去の故障や対処の知見が蓄積されており、デジタル化すれば保守支援に活用できます。",["活用を見送る"]]},"AIB-C01-211":{"0":["Polly の音声サンプルは音声合成の例にすぎず、生成 AI ワークロードの設計のベストプラクティスは示していません。",["音声サンプル"]],"1":["月次請求書は利用料金を示すだけで、設計上のベストプラクティスに照らした点検には使えません。",["月次請求書"]],"3":["AWS Marketplace はサードパーティ製品の購入窓口で、ワークロードの設計を点検するための指針ではありません。",["AWS Marketplace"]]},"AIB-C01-212":{"0":["各社員が空き時間に個別に整備すると、基準がばらつき品質も揃わず、計画的な整備になりません。",["各社員が空き時間に個別に"]],"1":["利用予定のないデータまで同じ優先度で整備すると、限られた予算が分散し、成果が出るまで時間がかかります。",["全データを同じ優先度"]],"3":["膨大なデータの整備完了を待つと AI の活用がいつまでも始まらず、成果を示して次の投資につなげられません。",["完了するまで"]]},"AIB-C01-213":{"0":["データ品質の問題はモデルの性能では補えません。品質の低いデータで学習すれば需要予測も不正確になります。",["品質の低いデータのまま"]],"2":["全社一括の統合は時間と費用がかかり、今年度中に需要予測で成果を出すという期限と予算の制約に合いません。",["すべてのデータを一度に統合"]],"3":["毎回の手作業による収集は再現性がなく工数もかかり、部門ごとにバラバラな品質の問題も解決しません。",["毎回各部門から手作業で"]]},"AIB-C01-214":{"1":["全面禁止では経験を積む機会がなくなり、高い関心や経営層の支援も生かせず、ガバナンス整備も進みません。",["あらゆる AI の利用を禁止"]],"2":["データガバナンスや利用ルールが未整備のまま顧客向けに公開すると、情報漏えいや不適切な回答のリスクが大きくなります。",["ルールが未整備のまま"]],"3":["利用ルールがない状態で外部サービスを自由に使わせると、シャドー AI による情報漏えいなど新たなリスクが生じます。",["各自が自由に外部の AI サービス"]]},"AIB-C01-215":{"0":["手書きのスキャン画像や年代ごとに異なる形式を扱うため、データ準備の費用がモデル利用料を上回ることもあり得ます。",["他の費用は考えなくてよい"]],"2":["手書き書類の読み取りは誤りが生じ得るうえ、形式もばらばらなため、整形や品質確認などの準備は不可欠です。",["すべて自動で正確に処理"]],"3":["データ準備を後回しにすると、運用開始後に予算超過や遅延が発覚します。承認前に計画へ含めるべきです。",["運用開始後に考えればよい"]]},"AIB-C01-216":{"1":["回答を短くしても、閲覧権限のない人事評価の情報が回答に含まれる可能性は残り、漏えいを防げません。",["回答の文字数を短くして"]],"2":["利用者を管理職に絞っても、管理職が閲覧できない文書が回答に出る問題は残り、根本的な解決になりません。",["管理職だけが使える"]],"3":["注意喚起だけでは、関連する質問で意図せず機密情報が回答に含まれることを防げません。技術的な権限制御が必要です。",["注意喚起するだけ"]]},"AIB-C01-217":{"0":["顧客データの利用制約を無視すると、法令や規程に違反し、顧客の信頼を損ないます。",["利用制約を無視して"]],"1":["合成データは実際の傾向と異なる可能性があります。実データでの検証を省くと、本番での性能を確かめられません。",["実データでの検証は省略"]],"2":["事例が少なくても、合成データで補うなどの方法があります。AI の活用を最初から諦める必要はありません。",["使うことはできないと結論付ける"]]},"AIB-C01-218":{"0":["現場任せでは部門間の調整や投資の確保ができず、全社的な方向性もそろいません。経営層の関与が不可欠です。",["現場の自主性に任せ"]],"2":["基盤モデルやツールの選定は技術的な判断で、実務の担当者に任せるべきです。経営層の主な役割ではありません。",["経営層自身が選定する"]],"3":["週次の進捗管理は実務の担当者が担う細かな管理で、経営層はビジョンの提示と資源配分に注力すべきです。",["直接、週次で行う"]]},"AIB-C01-219":{"0":["既存の手順に確認作業を追加すると、かえって手間が増えます。プロセス自体を見直さなければ大きな効果は得られません。",["AI による確認作業を追加する"]],"1":["モデルを高性能にしても既存の手順に組み込むだけでは、業務の構造が変わらず効果は限定的です。",["既存の手順に組み込む"]],"2":["手順を変えずに利用者を増やしても、AI を前提とした効率化は起きず、効果は限定的なままです。",["既存の手順を維持したまま"]]},"AIB-C01-220":{"1":["Bedrock の API を使った独自アプリは開発が必要で、自前開発なしで導入したいという要件に合いません。",["独自アプリの開発"]],"2":["Amazon Personalize は推薦機能に特化したサービスで、データ分析や問い合わせ回答、作業自動化のアシスタントではありません。",["Amazon Personalize"]],"3":["SageMaker AI はモデルの構築・学習・デプロイの基盤で、業務部門が自前開発なしで使えるアシスタントではありません。",["Amazon SageMaker AI"]]},"AIB-C01-221":{"0":["完全集中型は中央チームがすべてを担うため、各事業部門の業務知識を生かしにくく、部門に担当者を置くモデルとは異なります。",["完全集中型"]],"2":["外部委託一括型は AI 活用を外部に任せる形で、中央チームの標準化と部門担当者の組み合わせではありません。",["外部委託一括型"]],"3":["完全分散型は各部門が独自に進めるため中央の標準や共通基盤がなく、重複やばらつきが生じやすくなります。",["完全分散型"]]},"AIB-C01-222":{"0":["AI チャンピオンは監視や処分の役割ではありません。取り締まりを担わせると相談しにくくなり、利用の定着を妨げます。",["違反者を処分する"]],"1":["サーバー管理は IT 部門などの技術的な役割で、現場で活用を後押しするチャンピオンの目的ではありません。",["サーバーを管理する"]],"2":["予算の承認権限の集中はチャンピオンの役割ではなく、現場での活用の手本や相談相手という目的と異なります。",["予算の承認権限を集中"]]},"AIB-C01-223":{"0":["調達委員会は購買を審議する公式の会議体で、社員が自主的に事例やノウハウを共有し合う場ではありません。",["調達委員会"]],"2":["監査委員会は経営の監督や監査を担う公式の機関で、部門横断で知見を自主的に共有する場ではありません。",["監査委員会"]],"3":["取締役会は経営の意思決定機関で、AI に取り組む社員が自主的に学び合う場ではありません。",["取締役会"]]},"AIB-C01-224":{"1":["AWS Budgets は費用の予算を設定して超過を通知するサービスで、学習コンテンツは提供していません。",["AWS Budgets"]],"2":["AWS Cost Explorer は利用料金を分析するツールで、役割別に AWS の知識を学ぶ環境ではありません。",["AWS Cost Explorer"]],"3":["Amazon Macie は S3 内の機密データを検出するサービスで、社員教育のための学習環境ではありません。",["Amazon Macie"]]},"AIB-C01-225":{"0":["RAG は外部の文書を検索して生成 AI の回答に生かす技術で、タスクごとの役割と責任を整理する手法ではありません。",["RAG"]],"1":["KPI は目標の達成度を測る指標で、誰が実行し誰が最終責任を持つかを整理する手法ではありません。",["KPI"]],"2":["ROI は投資に対する利益の割合を示す指標で、役割分担の整理には使いません。",["ROI"]]},"AIB-C01-226":{"1":["業務時間外の試用を求めると社員の負担が増え、業務での活用にもつながりません。管理職の姿勢という原因も残ります。",["業務時間外に"]],"2":["管理職を通さない指示は業務の優先順位を決める管理職と矛盾し、現場が混乱します。管理職を巻き込む必要があります。",["管理職を通さずに"]],"3":["利用状況の確認をやめても、管理職が試用を認めていないという原因は変わらず、普及の状況も把握できなくなります。",["確認をやめる"]]},"AIB-C01-227":{"0":["議事録作成は事務的な作業で、権限ある後ろ盾として方向性を示す経営スポンサーの役割ではありません。",["議事録を作成する"]],"2":["モデルの技術的な設定は実務担当者の仕事で、経営スポンサーには資源確保や部門間の調整が期待されます。",["技術的な設定を自ら行う"]],"3":["利用履歴の日々の確認は細かな監視で、変革の方向性を示し資源を確保するスポンサーの役割ではありません。",["利用履歴を毎日確認する"]]},"AIB-C01-228":{"0":["年 1 回の報告会では知見が日常的に共有されず、部門ごとのばらばらな取り組みが続いて展開が加速しません。",["年 1 回の全社報告会"]],"2":["外部への全面委託では社内に能力やノウハウが残らず、持続的な全社展開の体制になりません。",["社内には推進組織を置かない"]],"3":["すべてを IT 部門に集約すると依頼が滞留し、各部門の業務知識も生かしにくくなり、展開が遅れます。",["IT 部門に集約し"]]},"AIB-C01-229":{"1":["一律の操作マニュアルでは自分の業務でどう使えばよいかが分からず、利用の定着につながりません。",["一律で同じ内容の操作マニュアル"]],"3":["利用が広がらない原因は業務での使い方が分からないことで、機能の多い製品に替えても解決しません。",["別の生成 AI 製品に入れ替える"]],"4":["利用回数を評価すると、成果につながらない形だけの利用を招き、本来の業務改善の目的から外れます。",["利用回数を人事評価の項目"]]},"AIB-C01-230":{"0":["説明を導入後に回すと、その間に不安と不信感が高まり、導入への抵抗が強まります。",["説明は導入後にまとめて"]],"1":["不安を表明した社員を外すと、現場の知見を失い、不安を口にしにくい雰囲気を作って不信を広げます。",["導入対象の業務から外す"]],"4":["計画を伏せると、後で知った社員の不信感が高まり、かえって不安と抵抗が大きくなります。",["社員に知らせない"]]},"AIB-C01-231":{"0":["全面委託では社内に知見が残らず、外部依存が続くため、中長期的に持続可能な体制になりません。",["すべての AI 開発と運用を外部パートナーに委託"]],"2":["育成が終わるまで取り組みを始めないと機会を逃します。外部の力を借りながら並行して育てるべきです。",["取り組みを始めない"]],"3":["AI 人材は市場での獲得競争が激しく、中途採用だけで必要な人数をすべて確保するのは困難です。",["中途採用だけで"]]},"AIB-C01-232":{"0":["予算消化率やプロジェクト件数は活動量を示すだけで、業務への効果や財務的な価値は分かりません。",["予算の消化率","プロジェクトの件数"]],"1":["リクエスト数や応答時間は技術的な利用状況を示すだけで、変革による業務成果や価値を表しません。",["月間リクエスト数","平均応答時間"]],"3":["ツール数や研修受講者数は取り組みの量を示すだけで、業務の効率化や売上への貢献は示せません。",["導入した AI ツールの数","受講者数"]]},"AIB-C01-233":{"0":["部門ごとに矛盾したルールを残すと、全社展開で混乱が生じ、リスク管理の一貫性も保てません。",["現状のまま維持する"]],"1":["ルールを廃止して個人の判断に任せると、情報漏えいや不適切な利用のリスクを統制できなくなります。",["ルールを廃止し"]],"2":["最も厳しいルールの一律適用で例外を認めないと、部門ごとの事情に対応できず、活用が大きく妨げられます。",["例外は一切認めない"]]},"AIB-C01-234":{"0":["ゼロから考えさせると、成功事例の知見が生かされず、展開に時間がかかって加速しません。",["ゼロから独自の方法"]],"1":["担当者 1 人に他部門の作業をすべて代行させると負荷が集中して持続せず、各部門に能力も残りません。",["作業をすべて代行させる"]],"3":["細部が異なる業務に同じ仕組みを強制すると、各部門の実情に合わず使われなくなるおそれがあります。",["細部まで変更せず","強制する"]]},"AIB-C01-235":{"0":["提供を停止すると活用の機会を失います。問題は利用料の可視化であり、基盤そのものではありません。",["基盤の提供を停止する"]],"2":["部門に知らせないと各部門がコストを意識せず、使い方の改善や予算の議論が進みません。",["部門には知らせない"]],"3":["均等割りでは実際の利用量と負担が一致せず、公平な予算配分にならず、コストを意識した利用も促せません。",["部門数で均等に割り当てる"]]},"AIB-C01-236":{"0":["業務部門の意見を導入後に聞くと、使えない仕組みが完成してから手戻りが発生し、頓挫の原因が解消されません。",["導入後に聞く"]],"2":["技術チームだけで開発して引き渡す方式こそ、業務部門に使えないと判断される原因です。分断を強めるだけです。",["技術チームだけで開発し"]],"3":["業務部門だけでは技術や法務・リスクの知見が不足し、品質や安全性に問題のある仕組みになりかねません。",["業務部門だけで"]]},"AIB-C01-237":{"0":["一度きりの決定事項の通知では、目的や影響が伝わらず、社員の理解と納得を得られません。",["一度メールで通知"]],"2":["不安の声に答えないと不信感が高まり、変革への抵抗が強まります。懸念を受け止める姿勢が必要です。",["回答しない方針"]],"4":["技術的な詳細だけでは、なぜ導入するのか、自分の仕事がどう変わるのかが伝わらず、納得につながりません。",["技術的な仕組みの詳細だけ"]]},"AIB-C01-238":{"1":["外部委託で罰するような対応は、効率化すると損をするという評価制度の矛盾を解消せず、社員の不信を招きます。",["外部に委託する"]],"2":["制度をそのままにして推奨しても、効率化すると手当が減るという動機の問題が残り、行動は変わりません。",["仕組みはそのままにして"]],"3":["義務化と処分は反発を招くだけで、効率化が不利になる報酬制度という根本原因に対処していません。",["利用しない社員を処分する"]]},"AIB-C01-239":{"0":["導入を中止すると効率化の機会を失います。担当者の役割を再設計すれば、人材を生かしながら導入できます。",["導入を中止して"]],"1":["業務を与えずに待機させると人材を無駄にし、社員の意欲も下がります。付加価値の高い業務へ再配置すべきです。",["待機させる"]],"3":["説明なしの業務廃止は社員の強い不信と抵抗を招き、変革の定着を妨げます。",["事前の説明なく"]]},"AIB-C01-240":{"0":["希望者だけで支援もないと、利用が一部にとどまり、3 部門で確認された効果を全社で得られません。",["支援は行わない"]],"1":["効果はすでに 3 部門で確認されており、同じパイロットを繰り返しても新たな知見は少なく、展開が遅れるだけです。",["もう一度 3 部門で同じパイロット"]],"3":["1 万人への一斉展開で問い合わせを各自に任せると、混乱が起き、支援がないため定着しません。",["同じ日に一斉に展開","各自で解決"]]},"AIB-C01-241":{"0":["AI アプリは利用者の声やモデルの変化に合わせて改善し続ける必要があり、変更しない方針では利用がさらに減ります。",["一切変更しない"]],"1":["不具合時だけの対応では、継続的な改善や成果への責任を持つ人がおらず、利用の減少は止まりません。",["不具合が出たときだけ"]],"3":["利用者には改善のための権限や技術がなく、責任の所在も曖昧になるため、継続的な改善は実現しません。",["利用者が自分で行う"]]},"AIB-C01-242":{"0":["処分では業務上のニーズという根本原因が解消されず、利用が隠れて行われるようになり、かえって把握が難しくなります。",["特定して処分する"]],"2":["対応しないと、承認外のサービスへの機密情報の入力などのリスクが放置され、統制できません。",["特に対応しない"]],"3":["実態を把握せずに即時禁止すると業務効率が下がり、ニーズが満たされないため隠れた利用が続くおそれがあります。",["実態を把握しないまま","即時に禁止"]]},"AIB-C01-243":{"0":["年 1 回だけで結果も通知しないと、提案が施策に反映されたか分からず、提案の意欲が失われます。",["結果は通知しない"]],"1":["提案者に費用を負担させると誰も提案しなくなり、現場のアイデアを集める仕組みとして機能しません。",["費用をすべて負担させる"]],"3":["経営企画部門だけで決める現行方式を続けると、現場の課題が反映されないという問題がそのまま残ります。",["現行の方式の継続"]]},"AIB-C01-244":{"0":["各部門がそれぞれツールを選ぶとツールが乱立し、セキュリティ部門が認めない状態になります。",["各部門が選んで導入"]],"1":["3 名で 1 部門ずつ個別に作り込むと時間がかかり、半年以内に 3 部門へ展開する期限に間に合いません。",["1 部門ずつ順番に","個別に作り込む"]],"3":["人事や経理は機密度が異なるため、設定をそのまま適用して利用者の注意に頼ると、情報の取り扱いを管理できません。",["利用者の注意で対応する"]]},"AIB-C01-245":{"0":["多くのパイロットは精度十分と報告されており、本番化しない原因はモデルの性能ではありません。やり直しは費用の無駄です。",["最も高性能なモデルでやり直す"]],"2":["技術部門の判断だけで本番化しても、業務部門の責任者や費用負担が決まっていないため、業務で使われず定着しません。",["技術部門の判断で本番化"]],"3":["件数を増やしても、責任者や費用負担が決まっていないという原因が残る限り、本番化の割合は改善しません。",["件数を増やし"]]},"AIB-C01-246":{"0":["一律の上限は業務価値の高い利用まで妨げ、品質の問題を利用者の注意に任せても根本的な改善になりません。",["一律の上限","利用者に注意を促して"]],"1":["問題が大きくなるまで放置すると、コスト増と品質低下が進み、責任の所在も曖昧なままです。",["問題が大きくなるまで"]],"3":["運用をすべてベンダーに任せると、社内で品質・コスト・リスクに責任を持つ人がいないままで、丸投げになります。",["運用をすべて任せる"]]},"AIB-C01-247":{"0":["現状維持では重複したチャットボットや把握されていない費用の無駄が続き、統制が取れません。",["現状の進め方を維持し"]],"1":["すべてを本社の承認制にすると、事業部の判断の速さが失われ、機動力を犠牲にします。",["事業部の判断権限をなくす"]],"3":["全面停止と 1 年間の凍結は、既存の価値も今後の機会も失う極端な対応で、統制と機動力の両立になりません。",["すべて停止し","1 年間凍結する"]]},"AIB-C01-248":{"0":["規制の違いは現地に合わせた調整で対応できます。展開しないと本社で上げた成果を海外拠点で生かせません。",["展開は行わない"]],"2":["本社の仕組みをそのまま展開すると、各地のデータ保護規制への違反や、言語・業務慣行に合わず使われないリスクがあります。",["変更せずに","同時に展開"]],"3":["各拠点にゼロから作らせると、本社の成果や共通基盤を再利用できず、重複と非効率が生じます。",["ゼロから独自の仕組み"]]},"AIB-C01-249":{"0":["低優先度の依頼を却下しても、CoE がすべてを開発するというボトルネックの構造は変わりません。",["すべて却下する"]],"2":["CoE を解散すると、標準やガバナンス、知見の共有が失われ、重複や統制の欠如が生じます。",["CoE を解散し"]],"3":["人員を倍増しても、すべてを CoE が開発する構造のままでは依頼の集中が続き、根本的な解決になりません。",["人員を倍増し"]]},"AIB-C01-250":{"0":["従業員代表を通さない個別交渉は、正式な協議の相手を無視する対応で、強い不信と反発を招きます。",["従業員代表を通さず"]],"1":["結果だけを事後に通知すると強い反発を招き、かえって定着が遅れて早期の効果も得られません。",["結果だけを通知する"]],"3":["無期限の延期は変革の機会を失い、早期に効果を出したいという経営層の目標を達成できません。",["無期限に延期する"]]},"AIF-C01-001":{"1":["包含関係が逆です。AI が最も広い概念で、ML はその中の一分野にあたります。ML が AI を含むわけではありません。",["AI を含む上位概念"]],"2":["AI は最も広い概念で、ディープラーニングは ML の中の一手法です。AI をディープラーニングの一手法とするのは包含関係が逆です。",["ディープラーニングの一手法"]],"3":["ディープラーニングは多層ニューラルネットワークでデータから学ぶ ML の一分野です。ML から独立した分野ではありません。",["ML とは独立した別の分野"]]},"AIF-C01-002":{"0":["自己教師あり学習はデータ自体から疑似的なラベルを作って学ぶ方式です。人が付けた「スパム」「正常」のラベルで学ぶこのケースは教師あり学習です。",["自己教師あり学習"]],"1":["教師なし学習はラベルのないデータから構造を見つける方式です。正解ラベル付きのメールで分類を学ぶこのケースには当てはまりません。",["教師なし学習"]],"2":["強化学習は環境との試行錯誤で報酬を最大化する方式です。ラベル付きデータから分類を学ぶこのケースとは異なります。",["強化学習"]]},"AIF-C01-003":{"0":["回帰は正解の数値が付いたデータから連続値を予測する教師あり学習です。ラベルのないデータから顧客グループを見つける目的には合いません。",["回帰"]],"1":["強化学習は報酬を手がかりに行動を学ぶ方式で、ラベルのない購買履歴を似た者同士にまとめる用途ではありません。",["強化学習"]],"3":["二値分類は 2 つの正解ラベルが付いたデータで学ぶ教師あり学習です。ラベルがない状態でグループを見つけることはできません。",["二値分類"]]},"AIF-C01-004":{"0":["クラスタリングはラベルのないデータを似たもの同士にまとめる手法で、賃料という連続値を予測するものではありません。",["クラスタリング"]],"2":["多クラス分類は決まったカテゴリから 1 つを選ぶタスクです。賃料のような連続した金額を予測するのは回帰です。",["多クラス分類"]],"3":["異常検知は通常と異なるデータを見つけるタスクで、物件の特徴から賃料の金額を予測する目的には合いません。",["異常検知"]]},"AIF-C01-005":{"0":["次元削減は高次元のデータを少ない変数に圧縮する教師なし学習の手法で、報酬を受けて行動を改善する仕組みではありません。",["次元削減"]],"1":["転移学習は学習済みモデルの知識を別のタスクに再利用する手法です。試行錯誤と報酬で行動を学ぶ方式そのものではありません。",["転移学習"]],"3":["教師あり学習は正解ラベル付きデータで学ぶ方式です。ロボットが試行錯誤し報酬で行動を改善するのは強化学習です。",["教師あり学習"]]},"AIF-C01-006":{"1":["学習はデータからモデルのパラメータを求める処理です。学習済みモデルに新しいデータを入れて予測を得る処理は推論と呼びます。",["学習"]],"2":["特徴量選択はモデルの入力に使う変数を選ぶ前処理の作業で、学習済みモデルで予測結果を得る処理ではありません。",["特徴量選択"]],"3":["ラベリングは学習データに正解を付ける作業です。学習済みモデルで新しいデータの予測を得る処理ではありません。",["ラベリング"]]},"AIF-C01-007":{"1":["CSV ファイルは行と列の決まった形を持つ表形式のデータで、構造化データにあたります。",["CSV ファイル"]],"2":["列と型が決まったテーブルは典型的な構造化データです。音声や画像のように決まった形を持たないデータではありません。",["列と型が決まった"]],"3":["リレーショナルデータベースの表は行と列で整理された構造化データで、非構造化データには該当しません。",["リレーショナルデータベースの表"]]},"AIF-C01-008":{"0":["コンピュータビジョンは画像や動画を扱う分野です。文章や話し言葉の意味を処理するのは自然言語処理です。",["コンピュータビジョン"]],"1":["強化学習は報酬で行動を学ぶ学習方式の一つで、言語の意味を理解・処理する AI の分野を指す名前ではありません。",["強化学習"]],"2":["時系列分析は時間順に並んだ数値データの傾向や将来値を扱う分野で、文章や言葉の意味を処理するものではありません。",["時系列分析"]]},"AIF-C01-009":{"0":["ストリーミング学習は流れてくるデータでモデルを更新し続ける学習の方式で、毎晩まとめて予測を出す推論方式ではありません。",["ストリーミング学習"]],"1":["リアルタイム推論は即時応答のためにエンドポイントを常時用意する方式です。1 日 1 回まとめて計算すればよいなら、コスト面で無駄が出ます。",["リアルタイム推論"]],"2":["エッジ推論は端末側で推論して低遅延やオフライン対応を実現する方式です。前日の全取引を夜間に一括処理する要件とは合いません。",["エッジ推論"]]},"AIF-C01-010":{"1":["高次元データを 2 次元に圧縮するのは次元削減で、正解ラベルを使わない教師なし学習のタスクです。",["2 次元に圧縮する"]],"2":["対戦を繰り返し報酬を最大化する戦略を学ぶのは強化学習で、正解ラベル付きデータから学ぶ教師あり学習ではありません。",["報酬を最大化する戦略"]],"4":["ラベルのない記事を内容の近さでグループ分けするのはクラスタリングで、教師なし学習のタスクです。",["ラベルのない記事"]]},"AIF-C01-011":{"0":["二値分類はカテゴリが 2 つの場合のタスクです。5 つのカテゴリから 1 つを選ぶこのケースは多クラス分類です。",["二値分類"]],"1":["回帰は連続した数値を予測するタスクです。メールを決まった部署のカテゴリに振り分ける用途には合いません。",["回帰"]],"2":["クラスタリングはあらかじめ決まったカテゴリなしにデータをまとめる手法です。指定した 5 つの部署に振り分けることはできません。",["クラスタリング"]]},"AIF-C01-012":{"0":["画像分類は画像をカテゴリに分けるタスクです。時間ごとの電力使用量から翌日の需要を見込む用途には合いません。",["画像分類"]],"1":["感情分析は文章の肯定・否定などを判定する自然言語処理のタスクで、数値の時系列から将来値を予測するものではありません。",["感情分析"]],"3":["クラスタリングは似たデータをまとめる手法で、時間の順序を持つ過去データから翌日の値を予測することはできません。",["クラスタリング"]]},"AIF-C01-013":{"0":["アンサンブル学習は複数のモデルの予測を組み合わせる手法です。学習済みモデルを出発点に自社画像で追加学習する手法ではありません。",["アンサンブル学習"]],"1":["次元削減は特徴量の数を減らす前処理的な手法で、学習済みモデルの知識を再利用して少量データで適応させるものではありません。",["次元削減"]],"3":["強化学習は報酬による試行錯誤で行動を学ぶ方式です。学習済みの画像モデルを自社データに適応させる用途とは異なります。",["強化学習"]]},"AIF-C01-014":{"1":["ルールベースのシステムは人が定義した規則で判断する仕組みで、ラベル付きとラベルなしのデータを組み合わせて学習するものではありません。",["ルールベースのシステム"]],"2":["教師なし学習だけではせっかくある 500 枚のラベル情報を使えません。少量のラベルと大量のラベルなしを併用するのは半教師あり学習です。",["教師なし学習のみ"]],"3":["強化学習は環境から得る報酬で行動を学ぶ方式で、ラベル付き・ラベルなしの医療画像を併用する学習には当てはまりません。",["強化学習"]]},"AIF-C01-015":{"0":["ディープラーニングは大量のデータを必要とします。学習データがほとんどない状態では性能が出にくく、利点は大きくありません。",["学習データがほとんどない"]],"1":["小さな表形式データで判断根拠の説明を重視する場面では、決定木などの従来手法のほうが適しており、ディープラーニングの利点は小さいです。",["判断根拠を明確に説明できる"]],"3":["決められた式で税額を求める処理は ML 自体が不要です。計算資源を最小限にしたい場合、ディープラーニングはむしろ不利です。",["決められた式で税額を求める"]]},"AIF-C01-016":{"0":["サーバーレス推論はペイロードサイズや処理時間の上限が小さく、最大 1 GB の動画を数分かけて解析する処理には対応できません。",["サーバーレス推論"]],"2":["リアルタイム推論は同期応答が前提でペイロードや処理時間の制約があり、インスタンスを 0 まで減らせないため夜間もコストがかかります。",["リアルタイム推論"]],"3":["毎晩 1 回のバッチ変換では、日中に随時届くリクエストを順次処理できず、利用者への結果通知が翌日まで遅れます。",["毎晩 1 回"]]},"AIF-C01-017":{"0":["非同期推論は大きなペイロードや長時間処理向けで、結果を S3 に出力してあとで受け取る方式です。数 KB の入力に数秒で応答する用途には過剰です。",["非同期推論"]],"1":["バッチ変換はまとまったデータを一括処理するジョブで、不規則に届く 1 件ずつのリクエストに数秒以内で応答できません。",["バッチ変換"]],"2":["常時稼働のインスタンスはリクエストがないアイドル時にも費用がかかり、1 日数十回の利用ではコストの無駄が大きくなります。",["常時稼働のインスタンス"]]},"AIF-C01-018":{"0":["正常時のデータだけでは故障の発生日という目的変数を学べず、回帰モデルで故障日を予測することはできません。",["故障の発生日を予測する"]],"1":["故障事例が数件しかないと分類モデルは汎化できず、見逃しや誤検知が多くなります。ラベルが乏しい場合は異常検知が適しています。",["故障事例の数件だけ"]],"3":["全センサー分の閾値を手作業で設定し見直さない方法は運用負荷が高く、パターンの変化にも追従できず早期検知に向きません。",["見直しは行わない"]]},"AIF-C01-019":{"0":["Comprehend はテキストの感情分析やエンティティ抽出を行う自然言語処理サービスで、画像から人物や物体を検出できません。",["Amazon Comprehend"]],"1":["Lex は音声・テキストの会話ボットを作るサービスで、監視カメラ画像の人物や物体の検出には使えません。",["Amazon Lex"]],"2":["Textract は文書から文字や表、フォームを抽出するサービスです。監視カメラ画像から人物や物体を検出する用途ではありません。",["Amazon Textract"]]},"AIF-C01-020":{"0":["Personalize は行動データに基づくレコメンデーションのサービスで、レビュー文から感情やキーフレーズを抽出する機能はありません。",["Amazon Personalize"]],"1":["Forecast は時系列データから将来の数値を予測するサービスで、文章の感情分析やキーフレーズ抽出は行えません。",["Amazon Forecast"]],"3":["Polly はテキストを音声に変換する音声合成サービスで、文章の感情やキーフレーズを分析する機能は持ちません。",["Amazon Polly"]]},"AIF-C01-021":{"1":["Rekognition は画像や動画を解析するサービスで、会議の音声をテキストに変換する機能はありません。",["Amazon Rekognition"]],"2":["Translate はテキストを別の言語に翻訳するサービスで、音声を入力として文字起こしすることはできません。",["Amazon Translate"]],"3":["Polly はテキストを音声に変換する逆方向のサービスです。音声からテキストへの変換は Transcribe が担います。",["Amazon Polly"]]},"AIF-C01-022":{"0":["Textract は文書画像から文字や表を抽出するサービスで、記事を音声で読み上げる機能はありません。",["Amazon Textract"]],"1":["Comprehend はテキストを分析する自然言語処理サービスで、テキストから音声を合成することはできません。",["Amazon Comprehend"]],"3":["Transcribe は音声をテキストに変換するサービスで、逆にテキストを音声で読み上げる用途には使えません。",["Amazon Transcribe"]]},"AIF-C01-023":{"0":["需要の変動パターンは決まった式で求められず、過去データから傾向を学ぶ ML が有効な典型例です。",["需要の変動パターンを予測する"]],"1":["大量の画像から不良品を見つける検査は、人がルールを書きにくいパターンを学べる ML が有効な典型例です。",["不良品を見つける検査"]],"4":["自由な文章である問い合わせの分類はルールで書き切りにくく、データからパターンを学ぶ ML が有効な場面です。",["問い合わせ文の分類"]]},"AIF-C01-024":{"0":["Translate はテキストを翻訳するサービスで、スキャンした PDF から請求元や金額、表を項目として抽出する機能はありません。",["Amazon Translate"]],"1":["Rekognition の文字検出は画像内の短いテキスト向けで、請求書のフォームのキーと値や表の構造は扱えません。",["Amazon Rekognition"]],"3":["Comprehend はテキストを分析するサービスで、スキャン画像から文字や表の構造を読み取る OCR 機能は持っていません。",["Amazon Comprehend"]]},"AIF-C01-025":{"1":["Transcribe は音声をテキストに変換するサービスで、投稿された口コミのテキストを他言語に翻訳することはできません。",["Amazon Transcribe"]],"2":["Lex は会話ボットを構築するサービスで、口コミを閲覧者の言語に機械翻訳する用途ではありません。",["Amazon Lex"]],"3":["Polly はテキストを音声に変換するサービスで、言語間の翻訳機能は持っていません。",["Amazon Polly"]]},"AIF-C01-026":{"0":["Polly はテキストを音声に変換するだけで、患者の発話から意図や日時を読み取って会話を進める機能はありません。",["Amazon Polly"]],"1":["Personalize はおすすめを提示するレコメンデーションサービスで、発話の意図とスロットを認識する対話ボットは作れません。",["Amazon Personalize"]],"3":["Textract は文書から文字や表を抽出するサービスで、電話やチャットの発話を理解して予約を受け付けることはできません。",["Amazon Textract"]]},"AIF-C01-027":{"0":["Comprehend はテキストの感情やエンティティを分析するサービスで、視聴履歴に基づく個人別のおすすめは生成できません。",["Amazon Comprehend"]],"1":["Rekognition は画像・動画の内容を解析するサービスで、利用者ごとの視聴履歴からおすすめを作る機能はありません。",["Amazon Rekognition"]],"2":["Kendra は自然言語の質問で文書を探す検索サービスで、行動履歴に基づく個人向けレコメンデーションを提供するものではありません。",["Amazon Kendra"]]},"AIF-C01-028":{"0":["Polly はテキストを音声に変換するサービスで、自然文の質問に対して社内文書の該当箇所を検索する機能はありません。",["Amazon Polly"]],"2":["Personalize は行動履歴に基づくレコメンデーションのサービスで、質問に答える文書検索には使えません。",["Amazon Personalize"]],"3":["Textract は文書から文字や表を抽出するだけで、自然文の質問に対して関連する箇所を探す検索機能は持ちません。",["Amazon Textract"]]},"AIF-C01-029":{"0":["Translate はテキストを翻訳するサービスで、診療記録から薬剤名や投与量などの医療エンティティを抽出できません。",["Amazon Translate"]],"2":["Polly はテキストを音声に変換するサービスで、医療テキストの内容を解析して情報を抽出する機能はありません。",["Amazon Polly"]],"3":["Rekognition は画像・動画を解析するサービスで、テキストの診療記録から医療情報を抽出する用途には使えません。",["Amazon Rekognition"]]},"AIF-C01-030":{"1":["Transcribe は音声をテキストに変換するサービスで、投稿画像の暴力的・性的な内容を検出することはできません。",["Amazon Transcribe"]],"2":["Textract は文書から文字や表を抽出するサービスで、画像に含まれる不適切なコンテンツを判定する機能はありません。",["Amazon Textract"]],"3":["Comprehend はテキストを分析するサービスで、画像そのものの内容をモデレーションすることはできません。",["Amazon Comprehend"]]},"AIF-C01-031":{"0":["パラメータ数を増やすことは導入可否の判断材料になりません。まず学習に使える解約データがあるかを確認しないと、モデルは作れません。",["パラメータ数を最大にできるか"]],"1":["GPU の確保は手段の話で、学習に必要な解約の記録データがなければ意味がありません。最初に確認すべきはデータの有無と品質です。",["最新の GPU インスタンス"]],"2":["生成 AI のチャットボットの有無は解約予測とは関係がありません。解約予測にはラベル付きの過去データが不可欠です。",["生成 AI のチャットボット"]]},"AIF-C01-032":{"1":["Polly はテキストを音声に変換するサービスで、通話録音をテキスト化したり不満を検出したりする機能はありません。",["Amazon Polly"]],"2":["Textract は文書画像から文字や表を読み取るサービスで、通話音声の処理や感情分析には使えません。",["Amazon Textract"]],"3":["Rekognition は画像・動画を解析するサービスで、通話音声の文字起こしやテキストの感情分析は行えません。",["Amazon Rekognition"]]},"AIF-C01-033":{"0":["最初に Translate を置いても、入力は音声なので翻訳できません。先に Transcribe で日本語音声をテキスト化する必要があります。",["Amazon Translate → Amazon Transcribe"]],"1":["Comprehend はテキスト分析用で音声を文字起こしできず、翻訳前に Polly で音声化しても英語の音声にはなりません。",["Amazon Comprehend → Amazon Polly"]],"3":["処理順が逆です。Polly はテキストを音声にするサービスで、最初に置いても日本語の音声入力を扱えません。",["Amazon Polly → Amazon Translate"]]},"AIF-C01-034":{"1":["Transcribe は音声をテキストに変換するサービスで、商品推薦にも説明文の生成にも使えません。",["Amazon Transcribe"]],"2":["Kendra は文書を検索するサービスで、閲覧履歴に基づく推薦や商品説明文の生成は行えません。",["Amazon Kendra"]],"3":["Textract は文書から文字や表を読み取るサービスで、推薦や文章生成の機能はありません。",["Amazon Textract"]]},"AIF-C01-035":{"1":["チャットボットに質問しても、数値データから学習した予測モデルがなければ根拠のある予測は得られず、毎週大量に実行する要件にも合いません。",["チャットボットに店舗スタッフが毎週予測を質問する"]],"2":["画像生成モデルはグラフの見た目を作るだけで、売上データから販売数を予測する機能はなく、根拠の説明もできません。",["画像生成モデル"]],"3":["毎回全データをプロンプトに渡すとトークン数が膨大になり推論コストが高く、数値の出力も安定せず根拠も説明しにくくなります。",["全データを毎回プロンプトとして渡して"]]},"AIF-C01-036":{"0":["モデルモニタリングはデプロイ後に本番の性能やデータの変化を監視する作業で、入力変数を作る作業ではありません。",["モデルモニタリング"]],"1":["ハイパーパラメータ調整は学習率などモデルの設定値を最適化する作業で、日付から曜日などの入力変数を作る作業とは異なります。",["ハイパーパラメータ調整"]],"3":["デプロイは学習済みモデルを本番で使える状態にする工程で、生データから特徴量を作る作業ではありません。",["モデルのデプロイ"]]},"AIF-C01-037":{"0":["SageMaker Neo は学習済みモデルを特定のハードウェア向けに最適化するコンパイル機能で、ノーコードでモデルを作る機能ではありません。",["SageMaker Neo"]],"2":["SageMaker Debugger は学習ジョブの内部状態を監視して問題を見つける開発者向け機能で、業務担当者がノーコードで予測モデルを作る用途ではありません。",["SageMaker Debugger"]],"3":["SageMaker Edge Manager はエッジデバイス上のモデルを管理する機能で、表形式データからノーコードで予測モデルを作る機能ではありません。",["SageMaker Edge Manager"]]},"AIF-C01-038":{"0":["モニタリングから始まりビジネス目標の定義が最後になっており、順序が逆です。目標を決めずにデータ収集や学習は進められません。",["モニタリング → モデルの学習"]],"1":["モデルがない段階でデプロイから始めることはできません。まず目標を定義し、データを準備して学習・評価してからデプロイします。",["デプロイ → データ収集"]],"3":["データ収集の前に学習を行う順序になっており成り立ちません。学習には事前に収集・前処理したデータが必要です。",["モデルの学習 → ビジネス目標の定義"]]},"AIF-C01-039":{"0":["データドリフトは本番の入力データの分布が学習時から変化する現象で、学習データにだけ過度に適合している状態を指す言葉ではありません。",["データドリフト"]],"1":["ハルシネーションは生成 AI が事実と異なる内容をもっともらしく出力する現象で、学習データと新規データの精度差を指すものではありません。",["ハルシネーション"]],"3":["過少適合は学習データでも精度が低い状態です。学習データで高精度なのに新しいデータで下がるのは過学習です。",["過少適合（アンダーフィッティング）"]]},"AIF-C01-040":{"0":["適合率は陽性と判定したもののうち本当に陽性だった割合で、誤検知を減らしたい場合の指標です。見逃しを避けるには再現率を重視します。",["適合率 (Precision)"]],"1":["RMSE は回帰モデルの誤差を測る指標で、画像分類で陽性患者の見逃しを評価する指標ではありません。",["RMSE"]],"2":["学習時間は計算コストの目安にすぎず、陽性患者をどれだけ見逃さずに検出できるかという性能は表しません。",["学習時間"]]},"AIF-C01-041":{"1":["テスト用データで調整を繰り返すとそのデータに合わせ込むことになり、本番で初めて見るデータに対する性能を過大に見積もります。",["テスト用データでハイパーパラメータを調整し続ける"]],"2":["学習データのコピーで評価すると、モデルが既に見たデータでの性能しか測れず、未知のデータに対する性能を過大に見積もります。",["そのままコピーしてテスト用データにする"]],"3":["学習に使った同じデータで精度を測ると過学習を見抜けず、本番での性能を過大に見積もってしまいます。",["同じデータで精度を測る"]]},"AIF-C01-042":{"0":["過少適合はモデルがパターンを捉えきれていない状態です。学習データを減らすとさらに学べる情報が減り、誤差は改善しません。",["半分に減らす"]],"2":["テストデータを学習に混ぜると正しい評価ができなくなるだけで、モデルの表現力不足という根本原因は解消しません。",["テストデータを学習データに混ぜて"]],"3":["正則化の強化はモデルを単純にする過学習への対策です。過少適合の状態で強めると、さらにパターンを捉えにくくなります。",["正則化をさらに強める"]]},"AIF-C01-043":{"0":["Model Cards はモデルの用途や性能などの情報を文書化する機能で、ハイパーパラメータの組み合わせを探索する機能はありません。",["SageMaker Model Cards"]],"2":["Model Monitor は本番のデータや予測の品質を監視する機能で、学習時にハイパーパラメータを探索するものではありません。",["SageMaker Model Monitor"]],"3":["Ground Truth は人によるデータのラベリングを管理する機能で、学習率などの設定値を自動で最適化することはできません。",["SageMaker Ground Truth"]]},"AIF-C01-044":{"0":["MSE は回帰モデルの予測誤差を測る指標で、迷惑メールの判定がどれだけ正しいかという分類の評価には使いません。",["平均二乗誤差 (MSE)"]],"1":["決定係数は回帰モデルがデータをどれだけ説明できるかを示す指標で、分類での誤検知の少なさは評価できません。",["決定係数 (R²)"]],"3":["再現率は実際の迷惑メールをどれだけ漏れなく捕まえたかの指標です。正常なメールの誤判定を減らしたいなら適合率を重視します。",["再現率 (Recall)"]]},"AIF-C01-045":{"0":["適合率は分類モデルの指標で、価格の予測が平均して何円ずれているかを表すことはできません。",["適合率 (Precision)"]],"1":["混同行列は分類結果の正誤を集計する表で、回帰の予測誤差を価格と同じ単位で示すものではありません。",["混同行列"]],"2":["AUC は分類モデルの判別性能を 0〜1 で表す指標で、価格の予測誤差を同じ単位で把握する用途には使えません。",["AUC"]]},"AIF-C01-046":{"1":["Ground Truth は人によるデータのラベリングを管理する機能で、本番環境の入力データの変化を継続的に監視することはできません。",["SageMaker Ground Truth"]],"2":["JumpStart は事前学習済みモデルやソリューションを使い始めるための機能で、本番モデルのドリフト検知は行いません。",["SageMaker JumpStart"]],"3":["Canvas はノーコードでモデルを作る機能で、デプロイ済みモデルの入力や予測の品質を継続的に監視する機能ではありません。",["SageMaker Canvas"]]},"AIF-C01-047":{"0":["Model Monitor は本番モデルのデータ品質やドリフトを監視する機能で、画像に人の手でラベルを付ける作業は管理できません。",["SageMaker Model Monitor"]],"2":["Clarify はデータやモデルのバイアス検出と予測の説明を行う機能で、作業者によるラベリングのワークフローは構築できません。",["SageMaker Clarify"]],"3":["自動モデルチューニングはハイパーパラメータを探索する機能で、学習データのラベル付け作業を効率化するものではありません。",["SageMaker 自動モデルチューニング"]]},"AIF-C01-048":{"0":["インスタンスサイズを上げても手作業による手順の抜けは防げず、上書きデプロイではモデルのバージョンや承認状態も管理できません。",["毎月上書きでデプロイする"]],"2":["手順書と個人 PC での保存は手作業のままで再現性が低く、承認されたモデルだけをデプロイする仕組みにもなりません。",["個人の PC に日付付きで保存する"]],"3":["ラベリングを増やしても処理の自動化やバージョン管理にはならず、評価を省略すると不合格のモデルが本番に出てしまいます。",["評価は省略する"]]},"AIF-C01-049":{"0":["不正を 1 件も検出できないモデルは正解率が高くても役に立ちません。偏ったデータでは正解率だけで判断してはいけません。",["そのまま本番にデプロイする"]],"2":["不正取引のデータを取り除くと、モデルは検出すべき不正のパターンをまったく学べなくなり、問題が悪化します。",["不正取引のデータを学習データから取り除く"]],"4":["学習データと同じデータで評価すると性能を過大に見積もるだけで、クラスの偏りによる見逃しの問題は解決しません。",["学習データと同じものにする"]]},"AIF-C01-050":{"0":["学習データの量は原因ではありません。予測時点で得られない将来の情報を特徴量に使っていることが、本番で精度が落ちる原因です。",["学習データを減らす"]],"1":["インスタンスの性能は推論速度に関わるだけで、予測精度の低下とは無関係です。原因は特徴量に含まれる将来の情報です。",["インスタンスサイズを上げる"]],"3":["検証データで異常に高い精度が出ているので過少適合ではありません。層を増やしてもデータリーケージは解消しません。",["過少適合している"]]},"AIF-C01-051":{"0":["エポックは学習データ全体を 1 回学習に使う単位で、LLM が入出力のテキストを処理する単位ではありません。",["エポック"]],"2":["バッチは学習や推論でまとめて処理するデータのかたまりを指し、単語や単語の一部に相当する単位ではありません。",["バッチ"]],"3":["ノードはニューラルネットワークの計算単位やネットワーク上の機器を指し、テキストを分割した単位ではありません。",["ノード"]]},"AIF-C01-052":{"0":["温度パラメータは生成時の出力のばらつきを調整する設定値で、文章の意味を数値の配列で表したものではありません。",["温度パラメータ"]],"1":["プロンプトはモデルに与える指示や入力の文章で、意味をベクトル空間に配置した数値表現ではありません。",["プロンプト"]],"2":["チェックポイントは学習途中のモデルの状態を保存したもので、文章の意味を表すベクトルではありません。",["チェックポイント"]]},"AIF-C01-053":{"0":["基盤モデルはファインチューニングや継続事前学習によって自社データで追加学習することもできます。追加学習に対応しないというのは誤りです。",["自社データでの追加学習には対応しない"]],"1":["基盤モデルは特定業界に限らない大量の多様なデータで事前学習されており、業界ごとに別のモデルが必要というわけではありません。",["特定の業界データだけで学習される"]],"2":["1 つのタスク専用に小さなデータで学習するのは従来型のモデルです。基盤モデルは大規模データで学習され多くのタスクに応用できます。",["特定の 1 タスクだけ"]]},"AIF-C01-054":{"1":["回帰モデルは数値を予測するモデルで、画像とテキストを同時に受け取って文章で回答することはできません。",["回帰モデル"]],"2":["単一モーダルモデルは 1 種類のデータしか扱えません。画像とテキストを同時に入力できるのはマルチモーダルモデルです。",["単一モーダルモデル"]],"3":["決定木モデルは主に表形式データの分類・回帰に使う手法で、画像の内容を文章で説明する機能はありません。",["決定木モデル"]]},"AIF-C01-055":{"1":["k 近傍法は近いデータの多数決などで分類・回帰を行う手法で、ノイズを除去しながら画像を生成する仕組みではありません。",["k 近傍法"]],"2":["ランダムフォレストは多数の決定木を組み合わせた分類・回帰の手法で、画像を生成するモデルではありません。",["ランダムフォレスト"]],"3":["線形回帰は数値を予測する単純なモデルで、ノイズから段階的に画像を生成する仕組みは持ちません。",["線形回帰"]]},"AIF-C01-056":{"0":["決定木は条件分岐で分類・回帰を行う従来型の ML 手法で、アテンションを中心としたニューラルネットワークではありません。",["決定木"]],"1":["k 平均法はデータをクラスタに分ける教師なし学習の手法で、LLM の基盤となるアーキテクチャではありません。",["k 平均法"]],"2":["サポートベクターマシンは分類などに使う従来型の ML 手法で、注意機構を持つニューラルネットワークではありません。",["サポートベクターマシン"]]},"AIF-C01-057":{"0":["LLM は入力を並べ替えるのではなく、文脈から次のトークンを確率的に予測して新しい文章を生成します。",["逆順に並べ替えて"]],"2":["用意された回答を検索して返すのは FAQ 検索の仕組みです。LLM はトークンを逐次予測して文章を生成します。",["データベースから検索して返す"]],"3":["人が定義した文法規則で文を組み立てるのは従来のルールベースの手法です。LLM はデータから学んだ確率で次のトークンを選びます。",["人が一つずつ定義したルール"]]},"AIF-C01-058":{"0":["線形回帰は数値を予測する単純なモデルで、生成器と識別器を競わせてデータを生成する仕組みは持ちません。",["線形回帰モデル"]],"2":["主成分分析はデータの次元を削減する教師なし学習の手法で、2 つのネットワークを競わせる生成モデルではありません。",["主成分分析 (PCA)"]],"3":["拡散モデルはノイズを段階的に除去して生成するモデルで、生成器と識別器を競わせる GAN とは仕組みが異なります。",["拡散モデル"]]},"AIF-C01-059":{"1":["最大トークン数は出力の長さの上限を決めるだけで、出力の一貫性やばらつきには影響しません。",["最大トークン数を増やす"]],"2":["温度を高くすると確率の低いトークンも選ばれやすくなり、出力のばらつきが増えて一貫性が下がります。",["温度 (temperature) を高くする"]],"3":["Top K を大きくすると候補となるトークンが増え、出力のばらつきが大きくなって一貫性が下がります。",["Top K を大きくする"]]},"AIF-C01-060":{"0":["最大トークン数は出力全体の長さの上限を決めるパラメータで、累積確率で次のトークン候補を絞るものではありません。",["最大トークン数"]],"1":["停止シーケンスは指定した文字列が出たら生成を止める設定で、トークン候補を確率で絞る仕組みではありません。",["停止シーケンス"]],"3":["エポック数は学習時にデータを何周使うかを決める値で、推論時のトークン選択には関係しません。",["エポック数"]]},"AIF-C01-061":{"1":["最大トークン数は出力の長さの上限を決めるもので、次のトークンを上位何個の候補から選ぶかは指定できません。",["最大トークン数"]],"2":["温度は確率分布の鋭さを変えて出力のばらつきを調整するもので、候補を上位 50 個に限定する設定ではありません。",["温度 (temperature)"]],"3":["Top-p は個数ではなく累積確率で候補を絞るパラメータです。上位 50 個という個数で絞るなら Top-k を使います。",["Top-p"]]},"AIF-C01-062":{"0":["Top-k は次のトークンを選ぶ候補の数を絞る設定で、応答全体の長さに上限を設けるものではありません。",["Top-k"]],"1":["学習率はモデルの学習時にパラメータの更新幅を決める値で、推論時の出力の長さとは関係ありません。",["学習率"]],"3":["温度は出力のばらつきを調整するパラメータで、応答の長さやそれに伴うコストを制限することはできません。",["温度 (temperature)"]]},"AIF-C01-063":{"0":["埋め込みの次元数は意味検索などのベクトル表現に関する設定で、テキスト生成をどこで止めるかには関係しません。",["埋め込みの次元数を増やす"]],"2":["Top-k を大きくすると候補が増えて出力がばらつくだけで、「Q:」の手前で生成を確実に止めることはできません。",["Top-k を大きくする"]],"3":["温度を高くすると出力のばらつきが増えるだけで、回答の終わりで生成を止める効果はありません。",["温度を高くする"]]},"AIF-C01-064":{"1":["サムネイル画像を生成しても検索の仕組みは変わらず、キーワードが異なる意味の近い記事は見つけられません。",["画像生成モデルで記事のサムネイルを作る"]],"2":["完全一致検索では「パスワードを忘れた」と表現が異なる「ログインできない場合の対処」の記事はヒットしません。",["完全一致検索"]],"3":["作成日順に並べるだけでは検索語との意味の近さが考慮されず、目的の記事を見つける助けになりません。",["作成日の新しい順に並べる"]]},"AIF-C01-065":{"0":["平均絶対誤差は回帰モデルの予測値と実測値のずれを測る指標で、ベクトル同士の向きの近さを測るものではありません。",["平均絶対誤差"]],"1":["パープレキシティは言語モデルが次のトークンをどれだけうまく予測できるかの指標で、2 つのベクトルの類似度ではありません。",["パープレキシティ"]],"2":["再現率は分類モデルが実際の陽性をどれだけ検出できたかの指標で、埋め込みベクトル間の意味の近さは測れません。",["再現率"]]},"AIF-C01-066":{"0":["評価から始まり事前学習が最後になっており順序が逆です。学習していないモデルは評価もデプロイもできません。",["評価 → デプロイ"]],"1":["デプロイが最初に来ていますが、事前学習も評価もしていないモデルはデプロイできません。",["デプロイ → 事前学習"]],"2":["ファインチューニングは事前学習済みのモデルに対して行うもので、データの選定や事前学習より前には実施できません。",["ファインチューニング → データの選定"]]},"AIF-C01-067":{"0":["Bedrock などの多くのサービスはトークン数に応じて課金されるため、トークン数が増えれば料金も増えます。",["料金に影響しない"]],"1":["トークンは文字数と常に一致するわけではなく、分割方法はモデルや言語によって異なります。",["文字数と常に等しい"]],"2":["通信の暗号化はトークン数とは無関係です。日本語で増えるのはモデルのトークン化の方法によるものです。",["暗号化されて送信される"]]},"AIF-C01-068":{"0":["温度は出力のばらつきを調整するパラメータで、出力の長さの上限には関係しないため、途中で途切れる問題は解決しません。",["温度を 0 にする"]],"1":["埋め込みモデルは検索用のベクトル化に使うもので、生成される文章の長さの上限到達とは関係ありません。",["埋め込みモデルを別のものに変更する"]],"3":["Top-k は次のトークンの候補数を絞る設定で、出力の長さの上限は変わらないため途切れは解消しません。",["Top-k を 1 にする"]]},"AIF-C01-069":{"0":["温度は生成時の出力のばらつきを調整するもので、検索段階でのベクトルの比較には影響しません。原因は質問と文書で埋め込みモデルが異なることです。",["生成用 LLM の温度を下げる"]],"2":["モデルごとにベクトル空間が異なるため、閾値を下げても意味の近さは測れず、無関係な文書が増えるだけです。",["類似度の閾値を下げる"]],"3":["モデル Y で作ったベクトルは質問文を工夫してもモデル X のベクトル空間には入りません。文書側も同じモデルで埋め込み直す必要があります。",["質問文を長くして"]]},"AIF-C01-070":{"0":["Top-k を 1 にすると常に最も確率の高いトークンだけが選ばれ、出力はかえって画一的になります。",["Top-k を 1 にする"]],"2":["停止シーケンスは指定した文字列で生成を止める設定で、案の多様性や意外性を高める効果はありません。",["停止シーケンスを追加する"]],"3":["最大トークン数を小さくすると出力が短くなるだけで、表現の多様性は増えません。",["最大トークン数を小さくする"]]},"AIF-C01-071":{"0":["モデルドリフトは時間とともに本番の状況が変わりモデル性能が低下する現象で、事実と異なる内容を生成する現象ではありません。",["モデルドリフト"]],"1":["過少適合はモデルが学習データのパターンを捉えきれていない状態で、もっともらしい誤情報の生成を指す言葉ではありません。",["過少適合"]],"3":["データ漏えいは機密情報が外部に流出することで、LLM が事実でない内容をもっともらしく生成する現象とは別物です。",["データ漏えい"]]},"AIF-C01-072":{"1":["固定ルールによる入力値の検証は毎回同じ結果が求められる処理で、確率的な生成 AI より従来のプログラムが適しています。",["固定ルールによる入力値の検証"]],"2":["法令で決まった税率の適用は正確さが必須の決まった処理で、従来のプログラムで行うべきものです。",["法令で定められた税率の適用"]],"4":["残高の計算は正確さが必須ですが、生成 AI は確率的にトークンを生成するため計算を誤ることがあり、適していません。",["残高の正確な計算"]]},"AIF-C01-073":{"0":["LLM は学習時点までの情報しか持たず、学習データにない最新情報を常に正しく答えることはできません。",["最新情報も常に正しく回答できる"]],"1":["生成 AI はハルシネーションを起こすことがあり、出力が事実として正確である保証はありません。",["常に事実として正確"]],"3":["生成は確率的に行われるため、同じ入力でも出力が変わることがあり、検証が不要になることはありません。",["必ず同じ出力を返す"]]},"AIF-C01-074":{"1":["テキストだけでなく画像なども扱えるマルチモーダルな LLM が存在するため、テキスト以外を一切扱えないというのは誤りです。",["テキスト以外のデータは一切扱えない"]],"2":["デプロイ後もインフラを拡張すれば利用者数は増やせます。これは LLM の本質的な限界ではありません。",["利用者数を増やせない"]],"3":["多くの LLM は多言語で学習されており日本語も扱えます。言語による品質差はあっても、扱えないわけではありません。",["日本語は扱えない"]]},"AIF-C01-075":{"0":["バックアップの物理的な保管は人や設備による作業で、生成 AI がテキストやコードを生成して支援する場面ではありません。",["物理的に保管する"]],"1":["ケーブルの修理は物理的な作業で、生成 AI の文章やコードの生成能力では対応できません。",["ネットワークケーブルの断線を修理する"]],"2":["CPU のクロック周波数はハードウェアの設定で、生成 AI によるコード生成の活用場面とは関係ありません。",["CPU のクロック周波数を上げる"]]},"AIF-C01-076":{"0":["生成 AI の出力は誤りを含むことがあり、法令適合性は人が確認する必要があります。人の確認なしに保証することはできません。",["人の確認なしで保証できる"]],"1":["SQL の実行速度はデータベースの性能の問題で、文章の作成を効率化する生成 AI の導入効果ではありません。",["SQL の実行速度が上がる"]],"3":["生成 AI の出力は確率的で、文面が変わらないことを保証する仕組みではありません。保存した文面の固定は生成 AI の効果ではありません。",["二度と変わらないことを保証できる"]]},"AIF-C01-077":{"0":["温度を 0 にすると最も確率の高いトークンが選ばれやすくなり、ばらつきは減ります。温度 0 の場合にだけ起こる現象ではありません。",["温度を 0 に設定している場合にだけ"]],"1":["推論のたびにモデルの重みが更新されることはありません。出力が変わるのはトークンを確率的に選んでいるためです。",["重みがリクエストのたびに少しずつ更新"]],"3":["会話の内容が都度モデルに学習されることはありません。ばらつきの原因は確率的なトークン選択です。",["その都度モデルに学習されている"]]},"AIF-C01-078":{"0":["温度は既に持っている知識からの選び方を変えるだけで、学習していない昨日の新制度の情報を生み出すことはできません。",["温度が低く"]],"1":["Top K は候補トークンの数を絞る設定で、モデルが知らない新しい情報を答えられるようにするものではありません。",["Top K が小さく設定されている"]],"3":["ゼロショットかどうかは指示の与え方の違いで、学習データにない昨日の情報を知らないという根本原因とは関係ありません。",["ゼロショットで書いている"]]},"AIF-C01-079":{"1":["パラメータ数はモデルの規模を示す技術的な情報で、チャットボット導入による業務改善やビジネス成果を表しません。",["モデルのパラメータ数"]],"2":["ROUGE は生成文と参照文の一致度を測る技術指標で、顧客満足や解決率といったビジネス価値を直接表しません。",["ROUGE スコア"]],"4":["平均入力トークン数はコストの見積もりに使う技術指標で、サポート業務のビジネス成果を示すものではありません。",["平均入力トークン数"]]},"AIF-C01-080":{"0":["誤った金額を顧客に送付すると信頼や取引に影響します。正確な計算はプログラムに任せれば誤りを防げます。",["そのまま顧客に送付する"]],"2":["指示を繰り返しても LLM が確率的に生成する仕組みは変わらず、計算の正確さは保証されません。",["繰り返し指示するだけにする"]],"3":["温度を上げると出力のばらつきが増え、誤りがかえって増えます。最大値を採用しても正しい合計になる保証はありません。",["最も大きい値を採用する"]]},"AIF-C01-081":{"0":["回答を長くしても根拠のない内容が減るわけではなく、かえって規程にない内容を含む余地が広がります。",["最大トークン数を大きくして"]],"2":["規程に関する指示を削除するとモデルが根拠を持たずに回答することになり、ハルシネーションが増えます。",["指示をすべて削除する"]],"3":["温度を上げると確率の低いトークンも選ばれやすくなり、事実と異なる内容がかえって出やすくなります。",["温度を最大値まで上げる"]]},"AIF-C01-082":{"0":["文字数の合計は売上への影響を示しません。効果は購入率などの業務指標を対照群と比べて測る必要があります。",["文字数の合計を数える"]],"1":["GPU の台数は生成にかかったリソースの話で、説明文が売上を伸ばしたかどうかは分かりません。",["GPU の台数を比較する"]],"3":["モデルのパラメータ数は規模を示すだけで、導入した説明文の売上への効果を評価する材料になりません。",["パラメータ数を報告する"]]},"AIF-C01-083":{"1":["モデル名を隠しても回答の根拠は分からず、利用者が正しさを確認しやすくはなりません。かえって透明性が下がります。",["モデルの名前を非表示にする"]],"2":["根拠を示さずに「正確です」と書いても検証の手段にはならず、誤った回答を信じ込ませる危険があります。",["「この回答は正確です」"]],"3":["文字数を短くしても回答の根拠は示されず、利用者が正しさを自分で確認する手段にはなりません。",["文字数を短くする"]]},"AIF-C01-084":{"0":["テストを廃止すると要約の品質低下を検知できなくなります。問題は評価基準であり、テスト自体をなくすべきではありません。",["テストを廃止する"]],"1":["偶然一致するまで再実行しても品質の評価にはならず、完全一致で判定するという基準の不適切さは解消しません。",["何度でも再実行する"]],"3":["期待値を結果に合わせて書き換えるとテストが常に合格し、誤った要約も検出できなくなります。",["テスト結果に合わせて書き換える"]]},"AIF-C01-085":{"0":["生成 AI はハルシネーションを起こすことがあり、誤りの影響が大きい医療分野で確認なしに患者へ送るのは危険です。",["そのまま患者に自動送信する"]],"1":["温度を上げると出力のばらつきが増え、誤った内容はかえって出やすくなります。確認なしの自動送信も危険です。",["温度を上げてから自動送信する"]],"2":["専門家が確認する運用にすればリスクを抑えて効率化できるため、活用を一切検討しないのは過度に保守的です。",["一切検討しない"]]},"AIF-C01-086":{"0":["生成 AI は問い合わせへの対応を効率化するもので、顧客からの問い合わせの発生そのものをなくすことはできません。",["件数そのものをゼロにできる"]],"1":["返金のような重要な判断を確認なしに生成 AI に任せるのは危険で、複雑な案件や判断は人に引き継ぐ設計にすべきです。",["スタッフの確認なしに返金処理を確定できる"]],"3":["生成 AI は文章の生成が得意なもので、将来の天候を正確に予言することはできません。",["天候を正確に予言できる"]]},"AIF-C01-087":{"0":["保険料率の算出は誤りの影響が大きく説明責任も求められる判断で、生成 AI に任せてそのまま反映するのは不適切です。",["そのまま約款に反映する"]],"1":["支払可否の最終決定は誤りの影響が大きく、人の確認なしに自動通知すると誤りを修正する機会がありません。",["支払可否を最終決定し"]],"3":["引き落とし金額の決定は顧客の資金に直結し、正確さが必須です。確率的な生成 AI に任せるのは不適切です。",["引き落とす金額を決める"]]},"AIF-C01-088":{"0":["検証せずに全社へ一斉導入すると費用が膨らむうえ、感想ではベースラインと比べた定量的な効果を示せません。",["全社に一斉導入し"]],"2":["ベンチマークスコアはモデルの一般的な性能で、自社業務での削減時間や総費用との比較という ROI の根拠にはなりません。",["ベンチマークスコアだけ"]],"3":["ROI はトークン料金だけでなく開発や運用を含む総費用で評価する必要があり、費用を過小に見積もることになります。",["開発や運用の費用は考慮しない"]]},"AIF-C01-089":{"0":["基盤モデルの性能は言語によって差があり、学習データの少ない言語では品質が下がることがあるため、英語の結果だけでは判断できません。",["すべての言語で同じ品質が出る"]],"1":["温度を上げると出力のばらつきが増えるだけで、学習データが少ない言語の回答品質は改善しません。",["温度を上げて回答を多様にする"]],"2":["最大トークン数を最小にすると回答が途中で途切れるだけで、言語ごとの品質差の確認や対策にはなりません。",["最大トークン数を最小にする"]]},"AIF-C01-090":{"0":["交渉メールの自動送信は誤りがそのまま相手方に伝わるおそれがあり、責任を持つ担当者の判断を経ないのは不適切です。",["交渉メールを自動送信させる"]],"1":["要約や条項の候補抽出に使い担当者が確認すれば効率化できるため、一切使わないのは効率化の機会を逃します。",["一切使わない"]],"2":["生成 AI は見落としやハルシネーションの可能性があるため、担当者が読まずに締結すると大きな損失につながります。",["担当者が読まずに締結する"]]},"AIF-C01-091":{"0":["Bedrock はサーバーレスで、利用者がインスタンスを選んで起動・管理する必要はありません。",["GPU インスタンスを選んで起動・管理し"]],"1":["Bedrock では入力したプロンプトや応答はベースモデルの学習に使われず、モデル提供者とも共有されません。",["モデル提供者と共有される"]],"2":["Bedrock では Amazon のモデルだけでなく、Anthropic や Meta など複数のプロバイダーのモデルを利用できます。",["Amazon が開発したモデルだけ"]]},"AIF-C01-092":{"1":["インスタンスの稼働時間で課金されるのは SageMaker AI のエンドポイントなどです。Bedrock のオンデマンドはトークン数で課金されます。",["GPU インスタンスの稼働時間"]],"2":["オンデマンドは使った分だけ支払う従量課金で、使用量に関係ない固定の月額料金はかかりません。",["固定の月額料金"]],"3":["テキストモデルのオンデマンド料金は入出力のトークン数に応じて決まり、長さに関係なく 1 回ごとに一定額ではありません。",["呼び出した回数のみ"]]},"AIF-C01-093":{"0":["Polly はテキストを音声に変換するサービスで、仕様の作成やコードの実装を支援する開発環境ではありません。",["Amazon Polly"]],"1":["Bedrock Guardrails は生成 AI の入出力を制御する機能で、要件から仕様やコードを作る IDE ではありません。",["Amazon Bedrock Guardrails"]],"2":["Rekognition は画像・動画を分析するサービスで、AI エージェントによる開発支援の機能はありません。",["Amazon Rekognition"]]},"AIF-C01-094":{"0":["Kendra は社内文書を検索するインテリジェント検索サービスで、基盤モデルのファミリーではありません。",["Amazon Kendra"]],"1":["Textract は文書から文字や表を抽出する AI サービスで、Bedrock で使う基盤モデルのファミリーではありません。",["Amazon Textract"]],"2":["Lex はチャットボットを構築するサービスで、Bedrock から利用する Amazon 製の基盤モデルではありません。",["Amazon Lex"]]},"AIF-C01-095":{"0":["Rekognition は画像・動画を解析するサービスで、Confluence や SharePoint の文書を取り込んで質問に回答する仕組みは作れません。",["Amazon Rekognition"]],"1":["想定問答を手作業で登録する方法は運用負荷が高く、社内文書が更新されても自動では追従できません。",["すべて手作業で登録する"]],"2":["JumpStart でのデプロイやファインチューニングは学習とインフラ管理が必要で、それを避けたいという要件に合いません。",["社内文書でファインチューニングする"]]},"AIF-C01-096":{"1":["Bedrock にスポットという購入方式はありません。中断の可能性があるスポットでは安定したスループットも確保できません。",["スポット"]],"2":["Savings Plans は EC2 などのコンピューティング利用料を割り引く仕組みで、Bedrock でカスタムモデルの処理能力を確保する方式ではありません。",["Savings Plans"]],"3":["オンデマンドは処理能力を確保しないためスロットリングの可能性があり、カスタマイズしたモデルの利用には通常プロビジョンドスループットが必要です。",["オンデマンド"]]},"AIF-C01-097":{"0":["AWS Glue はデータの抽出・変換・ロード (ETL) を行うサービスで、基盤モデルのデプロイやファインチューニングは行えません。",["AWS Glue"]],"2":["Comprehend は事前学習済みの自然言語処理サービスで、公開されている基盤モデルを選んで自社アカウントにデプロイする機能はありません。",["Amazon Comprehend"]],"3":["Kendra は文書検索サービスで、基盤モデルをワンクリックでデプロイしたり微調整したりする機能はありません。",["Amazon Kendra"]]},"AIF-C01-098":{"0":["50 万件を手動で 1 件ずつ実行するのは運用負荷が非常に高く、バッチ推論より料金も高くなります。",["1 件ずつリアルタイムで手動実行する"]],"1":["1 回限りの分類処理のために 1 年契約で処理能力を確保すると、処理後も費用がかかり続けコストを抑えられません。",["1 年契約で購入する"]],"3":["GPU サーバーの購入やモデル構築は初期費用と運用負荷が大きく、数日で結果が得られればよい今回の要件には過剰です。",["自社で GPU サーバーを購入して"]]},"AIF-C01-099":{"0":["Translate は機械翻訳のマネージドサービスで、オープンなモデルを改変したり学習やインスタンスを制御したりすることはできません。",["Amazon Translate"]],"1":["Amazon Q Business は社内データに基づくアシスタントサービスで、モデルの学習方法やインフラを細かく制御する用途ではありません。",["Amazon Q Business"]],"2":["Comprehend は事前学習済みの自然言語処理サービスで、独自のモデル改変や推論インスタンスの選択はできません。",["Amazon Comprehend"]]},"AIF-C01-100":{"0":["モデルを一から学習するのは大きな手間とコストがかかり、既存の基盤モデルの回答をコードなしで比較したいという目的に合いません。",["モデルを一から学習する"]],"2":["GPU インスタンスの起動やモデルのインストールは手間がかかり、Bedrock のモデルを手軽に比較する方法ではありません。",["GPU インスタンスを起動してモデルをインストールする"]],"3":["CloudFormation はインフラをコードで構築するサービスで、モデルにプロンプトを入力して回答を比較する機能はありません。",["AWS CloudFormation テンプレート"]]},"AIF-C01-101":{"1":["プロビジョンドスループットは期間契約で一定の処理能力に課金されるため、利用量が予測できず長期契約を避けたい段階には向きません。",["プロビジョンドスループットの 6 か月契約"]],"2":["自社に GPU サーバーを設置すると初期投資と運用負荷が大きく、試験運用で長期の負担を避けたい要件に反します。",["自社データセンターへの GPU サーバー設置"]],"3":["最大規模の処理能力を常時確保すると、利用が少ない日にも費用がかかり、変動する利用量に対して無駄が大きくなります。",["常時確保"]]},"AIF-C01-102":{"0":["Bedrock を使っても責任共有モデルは適用され、アクセス制御やデータの扱いは引き続き顧客の責任です。",["責任共有モデルが適用されず"]],"1":["Bedrock を使っても生成 AI のハルシネーションはなくならず、回答の正確性は保証されません。",["常に事実として正しい"]],"4":["Bedrock のモデルはトークン数などに応じた従量課金で、すべてが無料で使えるわけではありません。",["無料で利用できる"]]},"AIF-C01-103":{"0":["Guardrails は不適切な入出力をフィルタリングする機能で、繰り返し使う前置き部分の処理コストやレイテンシーは削減できません。",["Bedrock Guardrails"]],"1":["モデル評価はモデルの回答品質を比較・評価する機能で、リクエストごとの処理コストを減らす仕組みではありません。",["モデル評価"]],"2":["モデル呼び出しログは入出力を記録する機能で、前置き部分の再処理を省いてコストやレイテンシーを下げることはできません。",["モデル呼び出しログ"]]},"AIF-C01-104":{"0":["Translate は自然言語を翻訳するサービスで、モデルごとに異なる API リクエストの形式を変換する機能はありません。",["Amazon Translate"]],"2":["モデルを一から学習し直すのは膨大な手間とコストがかかり、リクエスト形式の書き換えを減らすという目的に見合いません。",["一から学習し直す"]],"3":["アカウントを分けてもモデルごとのリクエスト形式の違いは解消されず、管理の手間が増えるだけです。",["別の AWS アカウントを作成する"]]},"AIF-C01-105":{"0":["Comprehend は文章の分析を行うサービスで社内資料に基づく質問応答はできず、Guardrails も入出力の制御機能でコード生成は支援しません。",["Amazon Comprehend"]],"1":["Rekognition は画像・動画の分析、Transcribe は音声のテキスト化のサービスで、どちらの部門の要件にも合いません。",["Amazon Rekognition"]],"3":["組み合わせが逆です。社内資料に基づく質問応答はナレッジベースの RAG、仕様からコード生成までの支援は Kiro が適しています。",["営業部門には Kiro"]]},"AIF-C01-106":{"0":["最大量のプロビジョンドスループットを常時契約すると、利用の少ない時間帯にも費用が発生し、コスト最小化の要件に反します。",["常時契約する"]],"1":["バッチ推論は非同期のまとめ処理で、読者の質問に即時に答えるチャット機能には使えません。",["翌日にまとめて回答する"]],"3":["数万件を手作業でプレイグラウンドに貼り付けるのは現実的でなく、運用負荷が非常に高くなります。",["1 件ずつ手作業で"]]},"AIF-C01-107":{"0":["パブリックサブネットでインターネットに公開すると通信がインターネットを経由し、GPU を含むインフラの運用負荷も発生します。",["インターネットに公開する"]],"1":["海外のサービスにインターネット経由で接続すると、国内での処理や閉域での通信の要件を満たせません。",["インターネット経由で直接接続する"]],"2":["自社運用はデータ処理の要件は満たせても、GPU サーバーの運用を避けたいという要件に反します。",["GPU サーバーを購入し"]]},"AIF-C01-108":{"1":["自社ホスティングで常時稼働のエンドポイントを複数用意すると運用負荷とアイドル時の費用が大きく、専門家のいない小規模チームに向きません。",["常時稼働のエンドポイントを複数用意する"]],"2":["GPU インスタンスの予約と実行環境の構築は ML インフラの専門知識が必要で、変動する利用量に対しても費用の無駄が出ます。",["実行環境を自分たちで構築する"]],"3":["基盤モデルをゼロから学習するには膨大なデータとコストが必要で、1 か月で公開する小規模チームには現実的ではありません。",["ゼロから学習する"]]},"AIF-C01-109":{"0":["温度は出力のばらつきを調整するだけで、ピーク時のリクエスト数がクォータを超えるスロットリングは解消しません。",["温度を下げて応答を短くする"]],"2":["1 日中の最大量に合わせた長期契約は、利用の少ない時間帯にも費用がかかり、長期契約を避けたい要件にも反します。",["長期契約する"]],"3":["リクエストを破棄すると利用者の処理が失敗したままになります。再試行や処理能力の分散で対処すべきです。",["再送しない"]]},"AIF-C01-110":{"1":["1 回あたりは入力 0.002 USD と出力 0.002 USD の合計 0.004 USD で、10,000 回では 40 USD です。25 USD にはなりません。",["25 USD"]],"2":["1 回あたり 0.004 USD × 10,000 回 = 40 USD です。60 USD は入出力の料金の計算を誤った値です。",["60 USD"]],"3":["入力 2,000 トークンで 0.002 USD、出力 500 トークンで 0.002 USD、合計 0.004 USD × 10,000 回で 40 USD です。",["100 USD"]]},"AIF-C01-111":{"1":["Bedrock Agents は API などを呼び出して複数ステップのタスクを実行する機能で、文書の取り込みや埋め込み、格納を管理する機能ではありません。",["Amazon Bedrock Agents"]],"2":["モデル評価はモデルの回答品質を比較する機能で、S3 の文書をチャンク分割してベクトルストアに格納することはできません。",["モデル評価"]],"3":["Guardrails は不適切な入出力を制御する機能で、RAG 用のデータ取り込みや検索の仕組みは提供しません。",["Amazon Bedrock Guardrails"]]},"AIF-C01-112":{"1":["Athena は S3 上のデータに SQL でクエリを実行するサービスで、埋め込みベクトルを格納して類似検索するベクトルストアではありません。",["Amazon Athena"]],"3":["Kinesis Data Streams はストリーミングデータを取り込むサービスで、ベクトルを保存して類似検索する機能はありません。",["Kinesis Data Streams"]],"4":["Glue Data Catalog はデータのメタデータを管理するサービスで、埋め込みベクトルの保存や類似検索は行えません。",["AWS Glue Data Catalog"]]},"AIF-C01-113":{"0":["推論プロファイルはクロスリージョン推論などでリクエストの振り分け先を定義するもので、エージェントが呼び出す API を定義するものではありません。",["推論プロファイル"]],"1":["ガードレールは不適切な入出力を制御する仕組みで、API スキーマや Lambda などの実行先を定義する機能ではありません。",["ガードレール"]],"3":["モデル呼び出しログは入出力を記録する機能で、エージェントが外部処理を呼び出すための定義には使いません。",["モデル呼び出しログ"]]},"AIF-C01-114":{"1":["RAG はモデルの重みを変更せずに検索結果をプロンプトに加える手法で、質問ごとにファインチューニングすることはありません。",["ファインチューニングしてから"]],"2":["RAG は先に関連文書を検索し、その内容をもとに回答を生成します。生成後に検索して置き換える順序ではありません。",["回答を生成させた後に"]],"3":["RAG は学習データを作り直す手法ではなく、検索した情報を文脈として与えて回答を生成させる手法です。",["学習データを再作成する"]]},"AIF-C01-115":{"0":["PDF からテキストへの変換は文書の取り込み時の処理で、埋め込みモデルの役割はテキストをベクトルに変換することです。",["PDF からテキストに変換する"]],"1":["不適切な入力や出力のブロックは Guardrails の役割で、埋め込みモデルが担うものではありません。",["ブロックする"]],"3":["最終的な回答文を生成するのはテキスト生成モデルで、埋め込みモデルはテキストをベクトルに変換するだけです。",["最終的な回答文を生成する"]]},"AIF-C01-116":{"0":["ストリーミング応答は応答の体感速度を改善する機能で、料金は下がらず、大量処理のコスト削減策になりません。",["ストリーミング応答"]],"2":["1 件ずつリアルタイムで呼び出すと即時性が不要なのにバッチ推論より料金が高く、数十万件の処理では運用負荷も大きくなります。",["1 件ずつリアルタイムで呼び出す"]],"3":["月 1 回の処理のために 1 年契約で処理能力を確保すると、使わない期間も費用がかかりコストを抑えられません。",["1 年契約で購入する"]]},"AIF-C01-117":{"0":["ゼロからのモデル学習は膨大なデータとコストが必要で、再学習を避けたいという要件に真っ向から反します。",["ゼロからのモデル学習"]],"1":["継続事前学習はモデルを追加学習させる手法で、再学習を避けたい要件に合わず、マニュアルが更新されるたびに学習が必要になります。",["継続事前学習"]],"3":["Few-shot は回答の形式や傾向を示すもので、大量の社内マニュアルの最新内容を反映させることはできません。",["過去の回答例を数件示す"]]},"AIF-C01-118":{"0":["ゼロからの学習は最も手間とコストが大きい手法で、プロンプトエンジニアリングは最も手軽です。並びが誤っています。",["RAG → ゼロから学習"]],"2":["ファインチューニングは学習が必要で、RAG やプロンプトエンジニアリングより手間とコストが大きいため先頭に来ません。",["ファインチューニング → RAG"]],"3":["並びが逆です。最も手軽なのはプロンプトエンジニアリングで、ゼロからの学習が最も手間とコストが大きくなります。",["ゼロから学習 → ファインチューニング"]]},"AIF-C01-119":{"0":["パラメータ数が大きいモデルほど推論が遅くコストも高くなりがちで、応答速度を重視する簡単な分類には不向きです。",["最大のパラメータ数"]],"1":["対応言語の多さは今回の要件である応答速度や簡単な文章分類の精度とは直接関係しません。",["対応言語が最も多い"]],"2":["最大規模のモデルは簡単な分類には過剰で、レイテンシーが大きく、常時確保によりコストもかさみます。",["最大規模のモデル"]]},"AIF-C01-120":{"1":["ナレッジベースは文書を検索して回答に使う RAG の機能で、それだけでは在庫確認や注文の API を自律的に呼び出せません。",["ナレッジベースのみ"]],"2":["モデル評価はモデルの回答品質を比較する機能で、API を呼び出して複数ステップの処理を実行する仕組みではありません。",["Amazon Bedrock モデル評価"]],"3":["Comprehend はテキストを分析する自然言語処理サービスで、外部 API を順に呼び出してタスクを実行する機能はありません。",["Amazon Comprehend"]]},"AIF-C01-121":{"0":["画像生成への対応は多言語チャットボットの要件と関係がありません。確認すべきは対象言語への対応と品質です。",["画像生成に対応しているかどうか"]],"2":["提供開始日が新しくても、日本語・タイ語・ベトナム語で十分な品質が出るとは限りません。",["提供開始日が最も新しい"]],"3":["パラメータ数が大きくても、要件となる言語での回答品質が保証されるわけではなく、コストも高くなりがちです。",["パラメータ数が最も大きい"]]},"AIF-C01-122":{"0":["プロビジョンドスループットは処理能力を確保する購入方式で、分類や条件分岐を含むワークフローを組み立てる機能ではありません。",["プロビジョンドスループット"]],"2":["モデル呼び出しのロギングは入出力を記録する機能で、複数の処理をつないだワークフローを構築するものではありません。",["モデル呼び出しのロギング"]],"3":["モデル評価はモデルの回答品質を比較する機能で、ナレッジベースや Lambda をつなぐ処理の組み立てはできません。",["モデル評価"]]},"AIF-C01-123":{"0":["チャンクサイズは検索精度に関わる設定で、単一リージョンのクォータ上限によるスロットリングは解消しません。",["チャンクサイズを大きくする"]],"1":["Guardrails を無効にしても安全対策が失われるだけで、リクエスト数がクォータを超える問題は解決しません。",["Guardrails を無効にして"]],"2":["温度は出力のばらつきを調整するパラメータで、処理量を減らしてクォータの問題を解決する効果はありません。",["温度を下げて"]]},"AIF-C01-124":{"0":["埋め込みモデルを部署ごとに微調整しても検索対象の文書は絞り込めず、コストと手間が大きくなるだけです。",["部署ごとにファインチューニングする"]],"1":["温度は回答生成時のパラメータで、検索対象となる文書を制御することはできません。",["温度を 0 にして"]],"2":["最大トークン数は生成する出力の長さの上限で、どの部署の文書を検索対象にするかは制御できません。",["最大トークン数を減らして"]]},"AIF-C01-125":{"0":["ロギングは入出力を記録する機能で、繰り返し送る仕様書部分の処理時間や入力トークンのコストは削減できません。",["モデル呼び出しのロギング"]],"2":["温度を上げると出力のばらつきが増えるだけで、応答の遅さや入力トークンのコストは改善しません。",["温度の引き上げ"]],"3":["継続事前学習はモデルを追加学習させる手法で、学習コストがかかり、リクエストごとの入力コストを抑える機能ではありません。",["継続事前学習"]]}};
